tDef(133, "#{bold}##PURPLE#Every 10 levels starting at level 2 they gain a new unlocked generic tree, at random.#{normal}##LAST#", "_t", true) -- 
tDef(134, "#{bold}##GOLD#This is a bonus class for the chaotically inclined. It is by no means balanced, fun or winnable, it is most of all #{italic}#RANDOM#{bold}#.#WHITE##{normal}#", "_t", true) -- 
tDef(135, "Their most important stats depend on what they get to do.", "_t", true) -- 
tDef(139, "#GOLD#Life per level:#LIGHT_BLUE# +2", "_t", true) -- 
tDef(169, "#GOLD#As you level up you learn the talent tree: #LIGHT_BLUE#%s", "say", true) -- 
tDef(213, "Wanderer Seed", "_t", true) -- 


------------------------------------------------
section "mod-tome/data/birth/classes/afflicted.lua"

tDef(24, "Afflicted", "birth descriptor name", true) -- 
tDef(26, "Some walk in shadow, alone, unloved, unwanted. What powers they wield may be mighty, but their names are forever cursed.", "_t", true) -- 
tDef(28, "Afflicted classes have been twisted by their association with evil forces.", "_t", true) -- 
tDef(29, "They can use these forces to their advantage, but at a cost...", "_t", true) -- 
tDef(47, "Cursed", "birth descriptor name", true) -- 
tDef(49, "Affliction can run to the soul, and hatred can fill one's entire being. Overcome someone else's hated curse to know its dreaded meaning.", "_t", true) -- 
tDef(51, "Through ignorance, greed or folly the Cursed served some dark design and are now doomed to pay for their sins.", "_t", true) -- 
tDef(52, "Their only master now is the hatred they carry for every living thing.", "_t", true) -- 
tDef(53, "Drawing strength from the death of all they encounter, the Cursed become terrifying combatants.", "_t", true) -- 
tDef(54, "Worse, any who approach the Cursed can be driven mad by their terrible aura.", "_t", true) -- 
tDef(55, "Their most important stats are: Strength and Willpower", "_t", true) -- 
tDef(56, "#GOLD#Stat modifiers:", "_t", true) -- 
tDef(57, "#LIGHT_BLUE# * +5 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(58, "#LIGHT_BLUE# * +0 Magic, +4 Willpower, +0 Cunning", "_t", true) -- 
tDef(59, "#GOLD#Life per level:#LIGHT_BLUE# +2", "_t", true) -- 
tDef(117, "Doomed", "birth descriptor name", true) -- 
tDef(119, "In shaded places in unknown lands thou must overcome thyself and see thy doom.", "_t", true) -- 
tDef(121, "The Doomed are fallen mages who once wielded powerful magic wrought by ambition and dark bargains.", "_t", true) -- 
tDef(122, "Stripped of their magic by the dark forces that once served them, they have learned to harness the hatred that burns in their minds.", "_t", true) -- 
tDef(123, "Only time will tell if they can choose a new path or are doomed forever.", "_t", true) -- 
tDef(124, "The Doomed strike from behind a veil of darkness or a host of shadows.", "_t", true) -- 
tDef(125, "They feed upon their enemies as they unleash their minds on all who confront them.", "_t", true) -- 
tDef(126, "Their most important stats are: Willpower and Cunning", "_t", true) -- 
tDef(128, "#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(129, "#LIGHT_BLUE# * +0 Magic, +4 Willpower, +5 Cunning", "_t", true) -- 
tDef(130, "#GOLD#Life per level:#LIGHT_BLUE# +0", "_t", true) -- 


------------------------------------------------
section "mod-tome/data/birth/classes/celestial.lua"

tDef(21, "Celestial", "birth descriptor name", true) -- 
tDef(23, "The magic of the heavens is known to but a few, and that knowledge has long passed east, forgotten.", "_t", true) -- 
tDef(25, "Celestial classes are arcane users focused on the heavenly bodies.", "_t", true) -- 
tDef(26, "Most draw their powers from the Sun and the Moons.", "_t", true) -- 
tDef(58, "Sun Paladin", "birth descriptor name", true) -- 
tDef(60, "The sun rises in the east in full glory, but you must look for it first amidst the darkest places.", "_t", true) -- 
tDef(62, "Sun Paladins hail from the Gates of Morning, the last bastion of the free people in the Far East.", "_t", true) -- 
tDef(63, "Their way of life is well represented by their motto 'The Sun is our giver, our purity, our essence. We carry the light into dark places, and against our strength none shall pass.'", "_t", true) -- 
tDef(64, "They can channel the power of the Sun to smite all who seek to destroy the Sunwall.", "_t", true) -- 
tDef(65, "Competent in both weapon and shield combat and magic, they usually burn their foes from afar before bashing them in melee.", "_t", true) -- 
tDef(66, "Their most important stats are: Strength and Magic", "_t", true) -- 
tDef(67, "#GOLD#Stat modifiers:", "_t", true) -- 
tDef(68, "#LIGHT_BLUE# * +5 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(69, "#LIGHT_BLUE# * +4 Magic, +0 Willpower, +0 Cunning", "_t", true) -- 
tDef(70, "#GOLD#Life per level:#LIGHT_BLUE# +2", "_t", true) -- 
tDef(138, "Anorithil", "birth descriptor name", true) -- 
tDef(140, "The balance of the heavens' powers is a daunting task. Mighty are those that stand in the twilight places, wielding both light and darkness in their mind.", "_t", true) -- 
tDef(142, "Anorithils hail from the Gates of Morning, the last bastion of the free people in the Far East.", "_t", true) -- 
tDef(143, "Their way of life is well represented by their motto 'We stand betwixt the Sun and Moon, where light and darkness meet. In the grey twilight we seek our destiny.'", "_t", true) -- 
tDef(144, "They can channel the power of the Sun and the Moons to burn and tear apart all who seek to destroy the Sunwall.", "_t", true) -- 
tDef(145, "Masters of Sun and Moon magic, they usually burn their foes with Sun rays before calling the fury of the stars.", "_t", true) -- 
tDef(146, "Their most important stats are: Magic and Cunning", "_t", true) -- 
tDef(148, "#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(149, "#LIGHT_BLUE# * +6 Magic, +0 Willpower, +3 Cunning", "_t", true) -- 
tDef(150, "#GOLD#Life per level:#LIGHT_BLUE# +0", "_t", true) -- 


------------------------------------------------
section "mod-tome/data/birth/classes/chronomancer.lua"

tDef(24, "Chronomancer", "birth descriptor name", true) -- 
tDef(26, "Some do not walk upon the straight road others follow. Seek the hidden paths outside the normal course of life.", "_t", true) -- 
tDef(28, "Exploiting a hole in the fabric of spacetime, Chronomancers learn to pull threads from other timelines into their own.", "_t", true) -- 
tDef(29, "Pulling these threads creates tension and the harder they pull the more tension is produced.", "_t", true) -- 
tDef(30, "Constantly they manage this tension, which they call Paradox, to avoid or control the anomalies they inevitably unleash on the world around them.", "_t", true) -- 
tDef(60, "Paradox Mage", "birth descriptor name", true) -- 
tDef(62, "A hand may clap alone if it returns to clap itself. Search for the power in the paradox.", "_t", true) -- 
tDef(64, "A Paradox Mage studies the very fabric of spacetime, learning not just to bend it but shape it and remake it.", "_t", true) -- 
tDef(65, "Most Paradox Mages lack basic skills that others take for granted (like general fighting sense), but they make up for it through control of cosmic forces.", "_t", true) -- 
tDef(66, "Paradox Mages start off with knowledge of all but the most complex Chronomantic schools.", "_t", true) -- 
tDef(67, "Their most important stats are: Magic and Willpower", "_t", true) -- 
tDef(68, "#GOLD#Stat modifiers:", "_t", true) -- 
tDef(69, "#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +2 Constitution", "_t", true) -- 
tDef(70, "#LIGHT_BLUE# * +5 Magic, +2 Willpower, +0 Cunning", "_t", true) -- 
tDef(71, "#GOLD#Life per level:#LIGHT_BLUE# +0", "_t", true) -- 
tDef(150, "Temporal Warden", "birth descriptor name", true) -- 
tDef(152, "We preserve the past to protect the future. The hands of time are guarded by the arms of war.", "_t", true) -- 
tDef(154, "Their lifelines braided, Temporal Wardens have learned to work with their other selves across multiple timelines.", "_t", true) -- 
tDef(155, "Through their study of chronomancy, they learn to blend archery and dual-weapon fighting, seamlessly switching from one to the other.", "_t", true) -- 
tDef(156, "Their most important stats are: Magic, Dexterity, and Willpower", "_t", true) -- 
tDef(158, "#LIGHT_BLUE# * +0 Strength, +3 Dexterity, +0 Constitution", "_t", true) -- 
tDef(159, "#LIGHT_BLUE# * +4 Magic, +2 Willpower, +0 Cunning", "_t", true) -- 
tDef(160, "#GOLD#Life per level:#LIGHT_BLUE# +2", "_t", true) -- 


------------------------------------------------
section "mod-tome/data/birth/classes/corrupted.lua"

tDef(23, "Defiler", "birth descriptor name", true) -- 
tDef(25, "Dark thoughts, black bloods, vile deeds... Those who spill their brethren's blood will find its power.", "_t", true) -- 
tDef(27, "Defilers are touched by the mark of evil. They are a blight on the world. Working to promote the cause of evil, they serve their masters, or themselves become masters.", "_t", true) -- 
tDef(45, "Reaver", "birth descriptor name", true) -- 
tDef(47, "Reap thee the souls of thine enemies, and the powers of darkness shall enter thy flesh.", "_t", true) -- 
tDef(49, "Reavers are terrible foes, charging their enemies with a weapon in each hand.", "_t", true) -- 
tDef(50, "They can harness the blight of evil, infecting their foes with terrible contagious diseases while crushing their skulls with devastating combat techniques.", "_t", true) -- 
tDef(51, "Their most important stats are: Strength and Magic", "_t", true) -- 
tDef(52, "#GOLD#Stat modifiers:", "_t", true) -- 
tDef(53, "#LIGHT_BLUE# * +4 Strength, +1 Dexterity, +0 Constitution", "_t", true) -- 
tDef(54, "#LIGHT_BLUE# * +4 Magic, +0 Willpower, +0 Cunning", "_t", true) -- 
tDef(55, "#GOLD#Life per level:#LIGHT_BLUE# +2", "_t", true) -- 
tDef(114, "Corruptor", "birth descriptor name", true) -- 
tDef(116, "Blight and depravity hold the greatest powers. Accept temptation and become one with corruption.", "_t", true) -- 
tDef(118, "A corruptor is a terrible foe, wielding dark magics that can sap the very soul of her target.", "_t", true) -- 
tDef(119, "They can harness the blight of evil, crushing souls, stealing life force to replenish themselves.", "_t", true) -- 
tDef(120, "The most powerful corruptors can even take on some demonic aspects for themselves.", "_t", true) -- 
tDef(121, "Their most important stats are: Magic and Willpower", "_t", true) -- 
tDef(123, "#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +2 Constitution", "_t", true) -- 
tDef(124, "#LIGHT_BLUE# * +4 Magic, +3 Willpower, +0 Cunning", "_t", true) -- 
tDef(125, "#GOLD#Life per level:#LIGHT_BLUE# +0", "_t", true) -- 


