section "mod-tome/data/birth/classes/mage.lua"

tDef(36, "Mage", "birth descriptor name", true) -- 
tDef(38, "Mages are the wielders of arcane powers, able to cast powerful spells of destruction or to heal their wounds with nothing but a thought.", "_t", true) -- 
tDef(132, "Golem", "birth facial category", true) -- 
tDef(59, "Alchemist", "birth descriptor name", true) -- 
tDef(61, "An Alchemist is a manipulator of materials using magic.", "_t", true) -- 
tDef(62, "They do not use the forbidden arcane arts practised by the mages of old - such perverters of nature have been shunned or actively hunted down since the Spellblaze.", "_t", true) -- 
tDef(63, "Alchemists can transmute gems to bring forth elemental effects, turning them into balls of fire, torrents of acid, and other effects.  They can also reinforce armour with magical effects using gems, and channel arcane staffs to produce bolts of energy.", "_t", true) -- 
tDef(64, "Though normally physically weak, most alchemists are accompanied by magical golems which they construct and use as bodyguards.  These golems are enslaved to their master's will, and can grow in power as their master advances through the arts.", "_t", true) -- 
tDef(65, "Their most important stats are: Magic and Constitution", "_t", true) -- 
tDef(66, "#GOLD#Stat modifiers:", "_t", true) -- 
tDef(67, "#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +3 Constitution", "_t", true) -- 
tDef(68, "#LIGHT_BLUE# * +5 Magic, +1 Willpower, +0 Cunning", "_t", true) -- 
tDef(69, "#GOLD#Life per level:#LIGHT_BLUE# -1", "_t", true) -- 
tDef(134, "Golem becomes a Drolem", "_t", true) -- 
tDef(141, "Archmage", "birth descriptor name", true) -- 
tDef(143, "Hated, harrowed, hunted, hidden... Our ways are forbidden, but our cause is just. In our veiled valley we find solace from the world's wrath, free to study our arts. Only through charity and friendship can you earn our trust.", "_t", true) -- 
tDef(145, "An Archmage devotes his whole life to the study of magic above anything else.", "_t", true) -- 
tDef(146, "Most Archmagi lack basic skills that others take for granted (like general fighting sense), but they make up for it by their raw magical power.", "_t", true) -- 
tDef(147, "Archmagi start with knowledge of many schools of magic. However, they usually refuse to have anything to do with Necromancy.", "_t", true) -- 
tDef(148, "Most Archmagi have been trained in the secret town of Angolwen and possess a unique spell to teleport to it directly.", "_t", true) -- 
tDef(149, "Their most important stats are: Magic and Willpower", "_t", true) -- 
tDef(151, "#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(152, "#LIGHT_BLUE# * +5 Magic, +3 Willpower, +1 Cunning", "_t", true) -- 
tDef(153, "#GOLD#Life per level:#LIGHT_BLUE# -4", "_t", true) -- 
tDef(244, "Necromancer", "birth descriptor name", true) -- 
tDef(246, "The road to necromancy is a macabre path indeed. Walk with the dead, and drink deeply of their black knowledge.", "_t", true) -- 
tDef(248, "While most magic is viewed with suspicion since the Spellblaze, the stigma surrounding the black art of Necromancy has been around since time immemorial.", "_t", true) -- 
tDef(249, "These dark spellcasters extinguish life, twist death, and raise armies of undead monsters to sate their lust for power and pursue their ultimate goal: Eternal life.", "_t", true) -- 
tDef(254, "#GOLD#Life per level:#LIGHT_BLUE# -3", "_t", true) -- 


