section "mod-tome/data/birth/classes/none.lua"

tDef(21, "None", "birth descriptor name", true) -- 
tDef(23, "Your race cannot select a class; it has its own powers.", "_t", true) -- 


------------------------------------------------
section "mod-tome/data/birth/classes/psionic.lua"

tDef(24, "Psionic", "birth descriptor name", true) -- 
tDef(26, "Weakness of flesh can be overcome by mental prowess. Find the way and fight for the way to open the key to your mind.", "_t", true) -- 
tDef(28, "Psionics find their power within themselves. Their highly trained minds can harness energy from many different sources and manipulate it to produce physical effects.", "_t", true) -- 
tDef(46, "Mindslayer", "birth descriptor name", true) -- 
tDef(48, "A thought can inspire; a thought can kill. After centuries of oppression, years of imprisonment, a thought shall break us free and vengeance will strike from our darkest dreams.", "_t", true) -- 
tDef(50, "Mindslayers specialize in direct and brutal application of mental forces to their immediate surroundings.", "_t", true) -- 
tDef(51, "When Mindslayers do battle, they will most often be found in the thick of the fighting, vast energies churning around them and telekinetically-wielded weapons hewing nearby foes at the speed of thought.", "_t", true) -- 
tDef(52, "Their most important stats are: Willpower and Cunning", "_t", true) -- 
tDef(53, "#GOLD#Stat modifiers:", "_t", true) -- 
tDef(54, "#LIGHT_BLUE# * +1 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(55, "#LIGHT_BLUE# * +0 Magic, +4 Willpower, +4 Cunning", "_t", true) -- 
tDef(56, "#GOLD#Life per level:#LIGHT_BLUE# -2", "_t", true) -- 
tDef(137, "Solipsist", "birth descriptor name", true) -- 
tDef(139, "Some believe that the world is the collective dream of those that live in it.  Find and wake the sleeper and you'll unlock the potential of your dreams.", "_t", true) -- 
tDef(141, "The Solipsist believes that reality is malleable and nothing more than the collective vision of those that experience it.", "_t", true) -- 
tDef(142, "They wield this knowledge to both create and destroy, to invade the minds of others, and to manipulate the dreams of those around them.", "_t", true) -- 
tDef(143, "This knowledge comes with a heavy price and the Solipsist must guard his thoughts, lest he come to believe that the world exists only within his own mind.", "_t", true) -- 
tDef(146, "#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(147, "#LIGHT_BLUE# * +0 Magic, +5 Willpower, +4 Cunning", "_t", true) -- 
tDef(148, "#GOLD#Life per level:#LIGHT_BLUE# -4 (*special*)", "_t", true) -- 


------------------------------------------------
section "mod-tome/data/birth/classes/rogue.lua"

tDef(23, "Rogue", "birth descriptor name", true) -- 
tDef(25, "Rogues are masters of tricks; they can strike from the shadows, and lure monsters into deadly traps.", "_t", true) -- 
tDef(47, "Rogues are masters of tricks. A Rogue can get behind you unnoticed and stab you in the back for tremendous damage.", "_t", true) -- 
tDef(48, "Rogues usually prefer to dual-wield daggers. They can also become trapping experts, detecting and disarming traps as well as setting them.", "_t", true) -- 
tDef(49, "Their most important stats are: Dexterity and Cunning", "_t", true) -- 
tDef(50, "#GOLD#Stat modifiers:", "_t", true) -- 
tDef(51, "#LIGHT_BLUE# * +1 Strength, +3 Dexterity, +0 Constitution", "_t", true) -- 
tDef(52, "#LIGHT_BLUE# * +0 Magic, +0 Willpower, +5 Cunning", "_t", true) -- 
tDef(53, "#GOLD#Life per level:#LIGHT_BLUE# +0", "_t", true) -- 
tDef(100, "Shadowblade", "birth descriptor name", true) -- 
tDef(102, "Shadowblades are Rogues that are touched by the gift of magic, able to kill with their daggers under a veil of stealth while casting spells to enhance their performance and survival.", "_t", true) -- 
tDef(103, "Their use of magic is innate and not really studied; as such they do not naturally regenerate mana and must use external means of recharging.", "_t", true) -- 
tDef(104, "They use the schools of Phantasm, Temporal, Divination and Conveyance magic to enhance their arts.", "_t", true) -- 
tDef(105, "Their most important stats are: Dexterity, Cunning and Magic", "_t", true) -- 
tDef(107, "#LIGHT_BLUE# * +0 Strength, +3 Dexterity, +0 Constitution", "_t", true) -- 
tDef(108, "#LIGHT_BLUE# * +3 Magic, +0 Willpower, +3 Cunning", "_t", true) -- 
tDef(163, "Marauder", "birth descriptor name", true) -- 
tDef(165, "I will not hide and I will not sneak - come dance with my blades and we'll see who's weak. Snapping bone and cracking skull, it's the sounds of battle that make life full!", "_t", true) -- 
tDef(167, "The wilds of Maj'Eyal are not a safe place. Untamed beasts and wandering dragons may seem a great threat, but the true perils walk on two legs. Thieves and brigands, assassins and opportunistic adventurers, even mad wizards and magic-hating zealots all carry danger to those who venture beyond the safety of city walls.", "_t", true) -- 
tDef(168, "Amidst this chaos wanders one class of rogue that has learned to take by force rather than subterfuge. With refined techniques, agile feats and brawn-backed blades the Marauder seeks out his targets and removes them by the most direct methods. He uses dual weapons backed by advanced combat training to become highly effective in battle, and he is unafraid to use the dirtiest tactics when the odds are against him.", "_t", true) -- 
tDef(169, "Their most important stats are: Strength, Dexterity and Cunning", "_t", true) -- 
tDef(171, "#LIGHT_BLUE# * +4 Strength, +4 Dexterity, +0 Constitution", "_t", true) -- 
tDef(172, "#LIGHT_BLUE# * +0 Magic, +0 Willpower, +1 Cunning", "_t", true) -- 
tDef(225, "Skirmisher", "birth descriptor name", true) -- 
tDef(227, "Fleet of foot and strong of throw, overwhelming every foe, from afar we counter, strike and thud, in the chaos'd skirmish spilling blood.", "_t", true) -- 
tDef(229, "While able to take maximum advantage of their sling by using deft movements to avoid and confuse enemies that try to get close, the Skirmisher truly excels when fighting other ranged users.", "_t", true) -- 
tDef(230, "They have mastered the use of their shield as well as their sling and are nearly impossible to defeat in a standoff.", "_t", true) -- 
tDef(233, "#LIGHT_BLUE# * +0 Strength, +4 Dexterity, +0 Constitution", "_t", true) -- 
tDef(234, "#LIGHT_BLUE# * +0 Magic, +1 Willpower, +4 Cunning", "_t", true) -- 


------------------------------------------------
section "mod-tome/data/birth/classes/tutorial.lua"

tDef(21, "Tutorial Adventurer", "birth descriptor name", true) -- 
tDef(23, "Adventurers have a generic talent set to teach to young ones.", "_t", true) -- 


