section "mod-tome/data/birth/classes/warrior.lua"

tDef(24, "Warrior", "birth descriptor name", true) -- 
tDef(26, "Warriors train in all aspects of physical combat. They can be juggernauts of destruction wielding two-handed greatswords, or massive iron-clad protectors with gleaming shields.", "_t", true) -- 
tDef(47, "Berserker", "birth descriptor name", true) -- 
tDef(49, "A Berserker wields huge two-handed weapons of destruction, bringing pain and death to his foes as he cleaves them in two.", "_t", true) -- 
tDef(50, "A Berserker usually forfeits all ideas of self-defense to concentrate on what he does best: killing things.", "_t", true) -- 
tDef(51, "Their most important stats are: Strength and Constitution", "_t", true) -- 
tDef(52, "#GOLD#Stat modifiers:", "_t", true) -- 
tDef(53, "#LIGHT_BLUE# * +5 Strength, +1 Dexterity, +3 Constitution", "_t", true) -- 
tDef(54, "#LIGHT_BLUE# * +0 Magic, +0 Willpower, +0 Cunning", "_t", true) -- 
tDef(55, "#GOLD#Life per level:#LIGHT_BLUE# +3", "_t", true) -- 
tDef(114, "Bulwark", "birth descriptor name", true) -- 
tDef(116, "A Bulwark specializes in weapon and shield combat, rarely leaving the cover of her many protective techniques.", "_t", true) -- 
tDef(117, "A good Bulwark is able to withstand terrible attacks from all sides, protected by her shield, and when the time comes lash out at her foes with incredible strength.", "_t", true) -- 
tDef(118, "Their most important stats are: Strength and Dexterity", "_t", true) -- 
tDef(120, "#LIGHT_BLUE# * +5 Strength, +2 Dexterity, +2 Constitution", "_t", true) -- 
tDef(122, "#GOLD#Life per level:#LIGHT_BLUE# +6", "_t", true) -- 
tDef(184, "Archer", "birth descriptor name", true) -- 
tDef(186, "Archers are dexterous ranged fighters, able to pin their foes to the ground and rain down a carpet of arrows on them.", "_t", true) -- 
tDef(187, "Skilled archers can fire special shots that pierce, cripple or pin their foes.", "_t", true) -- 
tDef(188, "Archers can become good with either longbows or slings.", "_t", true) -- 
tDef(189, "Their most important stats are: Dexterity and Strength (when using bows) or Cunning (when using slings)", "_t", true) -- 
tDef(191, "#LIGHT_BLUE# * +2 Strength, +5 Dexterity, +0 Constitution", "_t", true) -- 
tDef(192, "#LIGHT_BLUE# * +0 Magic, +0 Willpower, +2 Cunning", "_t", true) -- 
tDef(193, "#GOLD#Life per level:#LIGHT_BLUE# +0", "_t", true) -- 
tDef(259, "Arcane Blade", "birth descriptor name", true) -- 
tDef(261, "The Arcane Blade is a warrior who has been touched by the gift of magic.", "_t", true) -- 
tDef(262, "Their use of magic is innate and not really studied; as such they do not naturally regenerate mana and must use external means of recharging.", "_t", true) -- 
tDef(263, "They can cast spells from a limited selection but have the unique capacity to 'channel' their attack spells through their melee attacks.", "_t", true) -- 
tDef(264, "They are adept with two-handed weapons, for the sheer destruction they can bring.", "_t", true) -- 
tDef(265, "Their most important stats are: Strength, Cunning and Magic", "_t", true) -- 
tDef(267, "#LIGHT_BLUE# * +3 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(268, "#LIGHT_BLUE# * +3 Magic, +0 Willpower, +3 Cunning", "_t", true) -- 
tDef(269, "#GOLD#Life per level:#LIGHT_BLUE# +2", "_t", true) -- 
tDef(337, "Brawler", "birth descriptor name", true) -- 
tDef(339, "Though you may fight alone against many, destined to fight till you die, still you do not relent. In a ring of blood you learn that a pair of fists can face the world.", "_t", true) -- 
tDef(341, "The ravages of the Spellblaze stretched armies thin and left many unprotected. Not everyone could afford the luxury of a weapon.", "_t", true) -- 
tDef(342, "Without steel or iron, poor communities of all races turned to the strength of their own bodies for defense against the darkness.", "_t", true) -- 
tDef(343, "Whether a pit-fighter, a boxer, or just an amateur practitioner, the Brawler's skills are still handy today.", "_t", true) -- 
tDef(344, "Many of the Brawler's abilities will earn combo points which they can use on finishing moves that will have added effect.", "_t", true) -- 
tDef(345, "The unarmed fighting styles the Brawler uses rely on maneuverability and having both hands available. As such, they cannot make use of their training wearing massive armour or while a weapon or shield is equipped.", "_t", true) -- 
tDef(346, "Their most important stats are: Strength, Dexterity, and Cunning", "_t", true) -- 
tDef(348, "#LIGHT_BLUE# * +3 Strength, +3 Dexterity, +0 Constitution", "_t", true) -- 
tDef(349, "#LIGHT_BLUE# * +0 Magic, +0 Willpower, +3 Cunning", "_t", true) -- 


