section "mod-tome/data/birth/classes/wilder.lua"

tDef(24, "Wilder", "birth descriptor name", true) -- 
tDef(26, "Natural abilities can go beyond mere skill. Experience the true powers of nature to learn of its amazing gifts.", "_t", true) -- 
tDef(28, "Wilders are one with nature, in one manner or another. There are as many different Wilders as there are aspects of nature.", "_t", true) -- 
tDef(29, "They can take on the aspects of creatures, summon creatures to them, feel the druidic call, ...", "_t", true) -- 
tDef(48, "Summoner", "birth descriptor name", true) -- 
tDef(50, "Not all might comes from within. Hear the invocations of nature, hear its calling power. See that from without we can find our true strengths.", "_t", true) -- 
tDef(52, "Summoners never fight alone. They are always ready to summon one of their many minions to fight at their side.", "_t", true) -- 
tDef(53, "Summons can range from a combat hound to a fire drake.", "_t", true) -- 
tDef(54, "Their most important stats are: Willpower and Cunning", "_t", true) -- 
tDef(55, "#GOLD#Stat modifiers:", "_t", true) -- 
tDef(56, "#LIGHT_BLUE# * +0 Strength, +1 Dexterity, +0 Constitution", "_t", true) -- 
tDef(57, "#LIGHT_BLUE# * +0 Magic, +5 Willpower, +3 Cunning", "_t", true) -- 
tDef(58, "#GOLD#Life per level:#LIGHT_BLUE# +0", "_t", true) -- 
tDef(63, "Max summons: %d", "tformat", true) -- 
tDef(110, "Wyrmic", "birth descriptor name", true) -- 
tDef(112, "Sleek, majestic, powerful... In the path of dragons we walk, and their breath is our breath. See their beating hearts with your eyes and taste their majesty between your teeth.", "_t", true) -- 
tDef(114, "Wyrmics are fighters who have learnt how to mimic some of the aspects of the dragons.", "_t", true) -- 
tDef(115, "They have access to talents normally belonging to the various kind of drakes.", "_t", true) -- 
tDef(116, "Their most important stats are: Strength and Willpower", "_t", true) -- 
tDef(118, "#LIGHT_BLUE# * +5 Strength, +0 Dexterity, +1 Constitution", "_t", true) -- 
tDef(119, "#LIGHT_BLUE# * +0 Magic, +3 Willpower, +0 Cunning", "_t", true) -- 
tDef(120, "#GOLD#Life per level:#LIGHT_BLUE# +2", "_t", true) -- 
tDef(181, "Oozemancer", "birth descriptor name", true) -- 
tDef(183, "Magic must fail, magic must lose, nothing arcane can face the ooze...", "_t", true) -- 
tDef(185, "Oozemancers separate themselves from normal civilisation so that they be more in harmony with Nature. Arcane force are reviled by them, and their natural attunement to the wilds lets them do battle with abusive magic-users on an equal footing.", "_t", true) -- 
tDef(186, "They can spawn oozes to protect and attack from a distance while also being adept at harnessing the power of mindstars and psiblades.", "_t", true) -- 
tDef(189, "#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(190, "#LIGHT_BLUE# * +0 Magic, +5 Willpower, +4 Cunning", "_t", true) -- 
tDef(191, "#GOLD#Life per level:#LIGHT_BLUE# -3", "_t", true) -- 
tDef(258, "Stone Warden", "birth descriptor name", true) -- 
tDef(260, "The Spellblaze's scars may be starting to heal,\
but little can change how the partisans feel.\
Nature and arcane could bridge their divide -\
and when it comes down to it, gold won't take sides...", "_t", true) -- 
tDef(262, "Stone Wardens are dwarves trained in both the eldritch arts and the worship of nature.", "_t", true) -- 
tDef(263, "While other races are stuck in their belief that arcane forces and natural forces are meant to oppose, dwarves have found a way to combine them in harmony.", "_t", true) -- 
tDef(264, "Stone Wardens are armoured fighters, dual wielding shields to channel many of their powers.", "_t", true) -- 
tDef(265, "Their most important stats are: Strength, Magic and Willpower", "_t", true) -- 
tDef(267, "#LIGHT_BLUE# * +2 Strength, +0 Dexterity, +0 Constitution", "_t", true) -- 
tDef(268, "#LIGHT_BLUE# * +4 Magic, +3 Willpower, +0 Cunning", "_t", true) -- 


