section "mod-tome/data/birth/descriptors.lua"

tDef(32, "base", "birth descriptor name", true) -- 
tDef(98, "Tutorial", "birth descriptor name", true) -- 
tDef(102, "#GOLD##{bold}#Tutorial mode", "_t", true) -- 
tDef(103, "#WHITE#Start with a simplified character and discover the game in a simple quest.#{normal}#", "_t", true) -- 
tDef(104, "All damage done to the player reduced by 20%", "_t", true) -- 
tDef(105, "All healing for the player increased by 10%", "_t", true) -- 
tDef(106, "No main game achievements possible.", "_t", true) -- 
tDef(149, "Easier", "birth descriptor name", true) -- 
tDef(153, "#GOLD##{bold}#Easier mode#WHITE##{normal}#", "_t", true) -- 
tDef(154, "Provides an easier game experience.", "_t", true) -- 
tDef(155, "Use it if you feel uneasy tackling the harder modes.", "_t", true) -- 
tDef(156, "All damage done to the player decreased by 30%", "_t", true) -- 
tDef(157, "All healing for the player increased by 30%", "_t", true) -- 
tDef(158, "All detrimental status effects durations reduced by 50%", "_t", true) -- 
tDef(159, "Achievements are not granted.", "_t", true) -- 
tDef(173, "Normal", "birth descriptor name", true) -- 
tDef(177, "#GOLD##{bold}#Normal mode#WHITE##{normal}#", "_t", true) -- 
tDef(178, "Provides the normal level of challenges.", "_t", true) -- 
tDef(179, "Stairs can not be used for 2 turns after a kill.", "_t", true) -- 
tDef(193, "Nightmare", "birth descriptor name", true) -- 
tDef(197, "#GOLD##{bold}#Nightmare mode#WHITE##{normal}#", "_t", true) -- 
tDef(198, "Unfair game setting", "_t", true) -- 
tDef(199, "All zone levels increased by 25% by the time Player reaches level 10", "_t", true) -- 
tDef(200, "All creature talent levels increased by 30%", "_t", true) -- 
tDef(201, "Unique (fixed) bosses advance in bonus classes 30% faster", "_t", true) -- 
tDef(202, "Rare creatures are slightly more frequent", "_t", true) -- 
tDef(203, "Stairs can not be used for 3 turns after a kill.", "_t", true) -- 
tDef(204, "Player can earn Nightmare version of achievements if also playing in Roguelike or Adventure permadeath mode.", "_t", true) -- 
tDef(228, "Insane", "birth descriptor name", true) -- 
tDef(230, "Easy is for the weak! Normal is for the weak! Nightmare is too easy! Bring on the true pain!", "_t", true) -- 
tDef(234, "#GOLD##{bold}#Insane mode#WHITE##{normal}#", "_t", true) -- 
tDef(235, "Similar rules to Nightmare, but with more random bosses!", "_t", true) -- 
tDef(236, "All zone levels increased by 50% + 1 by the time Player reaches level 10", "_t", true) -- 
tDef(237, "All creature talent levels increased by 70%", "_t", true) -- 
tDef(238, "Unique (fixed) bosses advance in bonus classes 70% faster", "_t", true) -- 
tDef(239, "Rare creatures are far more frequent and random bosses start to appear", "_t", true) -- 
tDef(240, "Stairs can not be used for 5 turns after a kill.", "_t", true) -- 
tDef(241, "Player can earn Insane version of achievements if also playing in Roguelike or Adventure permadeath mode.", "_t", true) -- 
tDef(266, "Madness", "birth descriptor name", true) -- 
tDef(268, "Insane is for the weak! Bring on the true mind-shattering experience!", "_t", true) -- 
tDef(272, "#GOLD##{bold}#Madness mode#WHITE##{normal}#", "_t", true) -- 
tDef(273, "Absolutely unfair game setting. Prepare for the full wrath of DarkGod!", "_t", true) -- 
tDef(274, "All zone levels increased by 150% + 2 by the time Player reaches level 10", "_t", true) -- 
tDef(275, "All creature talent levels increased by 170%", "_t", true) -- 
tDef(276, "Unique (fixed) bosses advance in bonus classes 170% faster", "_t", true) -- 
tDef(277, "All enemies have 200% more life", "_t", true) -- 
tDef(279, "Stairs can not be used for 9 turns after a kill.", "_t", true) -- 
tDef(280, "Player starts with 100 more life and 500 gold, but trust us, you'll need it!", "_t", true) -- 
tDef(281, "Player is being hunted! Randomly all foes in a radius will get a feeling of where she/he is", "_t", true) -- 
tDef(282, "Player can earn Madness version of achievements if also playing in Roguelike or Adventure permadeath mode.", "_t", true) -- 
tDef(314, "Exploration", "birth descriptor name", true) -- 
tDef(316, "Exploration mode: Infinite lives (donator feature)", "_t", true) -- 
tDef(321, "#GOLD##{bold}#Exploration mode#WHITE#", "_t", true) -- 
tDef(322, "Provides you with infinite lives.#{normal}#", "_t", true) -- 
tDef(323, "This is not the way the game is meant to be played, but it allows you to have a more forgiving experience.", "_t", true) -- 
tDef(324, "Remember though that dying is an integral part of the game and helps you become a better player.", "_t", true) -- 
tDef(325, "Exploration version of achievements will be granted in this mode.", "_t", true) -- 
tDef(326, "Full talent respec is always available.", "_t", true) -- 
tDef(338, "Adventure", "birth descriptor name", true) -- 
tDef(342, "#GOLD##{bold}#Adventure mode#WHITE#", "_t", true) -- 
tDef(343, "Provides you with limited extra lives.", "_t", true) -- 
tDef(344, "Use it if you want normal playing conditions but do not feel ready for just one life.#{normal}#", "_t", true) -- 
tDef(345, "At level 1,2,5,7,14,24,35 get one more 'life' that allows you to resurrect at the start of the level.", "_t", true) -- 
tDef(353, "Roguelike", "birth descriptor name", true) -- 
tDef(357, "#GOLD##{bold}#Roguelike mode#WHITE#", "_t", true) -- 
tDef(358, "Provides the closer experience to 'classic' roguelike games.", "_t", true) -- 
tDef(359, "You will only have one life; you *ARE* your character.#{normal}#", "_t", true) -- 
tDef(360, "Only one life, unless ways to self-resurrect are found in-game.", "_t", true) -- 


