section "mod-tome/data/birth/races/giant.lua"

tDef(24, "Giant", "birth descriptor name", true) -- 
tDef(26, "Powerful beings that tower over all, but the bigger they are, the harder they fall...", "_t", true) -- 
tDef(28, "#{italic}#\"Giant\"#{normal}# is a catch-all term for humanoids which are typically over eight feet in height.  Their origins, cultures, and relationships to other races differ wildly, but they tend to live as refugees and outcasts, shunned by smaller sentient races who usually see them as a threat.", "_t", true) -- 
tDef(92, "Skin", "birth facial category", true) -- 
tDef(92, "Hairs", "birth facial category", true) -- 
