section "mod-tome/data/birth/worlds.lua"

tDef(69, "Maj'Eyal: The Age of Ascendancy", "_t", true) -- 
tDef(73, "The people of Maj'Eyal: Humans, Halflings, Elves and Dwarves.", "_t", true) -- 
tDef(74, "The known world has been at relative peace for over one hundred years, and people are prospering again.", "_t", true) -- 
tDef(75, "You are an adventurer, setting out to find lost treasure and glory.", "_t", true) -- 
tDef(76, "But what lurks in the shadows of the world?", "_t", true) -- 
tDef(124, "Infinite Dungeon: The Neverending Descent", "_t", true) -- 
tDef(126, "Ever deeper, never ending, no reprieve, keep descending. In ruins old, through barred gate, once riddle solved, find thy fate.", "_t", true) -- 
tDef(130, "Play as your favorite race and class and venture into the infinite dungeon.", "_t", true) -- 
tDef(131, "The only limit to how far you can go is your own skill!", "_t", true) -- 
tDef(132, "Inside the infinite dungeon you will yourself be limitless. You can level up beyond level 50 and continue to gain stat and talent points (at a reduced rate).", "_t", true) -- 
tDef(133, "Every level after level 50 the maximum of stats will increase by one.", "_t", true) -- 
tDef(134, "Every 10 levels after level 50 the maximum points of each talent will increase by one.", "_t", true) -- 
tDef(200, "The Arena: Challenge of the Master", "_t", true) -- 
tDef(202, "Blood spilled on sand, only the strong survive. Prove yourself worthy to enter.", "_t", true) -- 
tDef(206, "Play as a lone warrior facing the Arena's challenge!", "_t", true) -- 
tDef(207, "You can use any class and race for it.", "_t", true) -- 
tDef(208, "See how far you can go! Can you become the new Master of the Arena?", "_t", true) -- 
tDef(209, "If so, you will battle your own champion next time!", "_t", true) -- 


