tDef(22, "Equipment(%s) <=> Inventory(%s)", "tformat", true) -- 
tDef(51, "Change your golem's name", "_t", true) -- 
tDef(51, "Name", "_t", true) -- 
tDef(53, "%s (servant of %s)", "tformat", true) -- 
tDef(67, "I want to change your equipment.", "_t", true) -- 
tDef(68, "I want to change your talents.", "_t", true) -- 
tDef(69, "I want to change your tactics.", "_t", true) -- 
tDef(70, "I want to take direct control.", "_t", true) -- 
tDef(71, "I want to change your name.", "_t", true) -- 
tDef(71, "Telos the Great and Powerful (reluctant follower of %s)", "tformat", true) -- 
tDef(71, "#ROYAL_BLUE#The golem decides to change it's name to #{bold}#%s#{normal}#.", "log", true) -- 
tDef(73, "How is it that you speak?", "_t", true) -- 
tDef(74, "I want to change your appearance (one-time only).", "_t", true) -- 
tDef(75, "Nothing, let's go.", "_t", true) -- 
tDef(79, "What's the good of immortality if you can't even speak? No archmage worth his salt is going to concoct some immoral life-after-death scheme without including some sort of capacity for making his opinions known. And, by the way, your energy manipulation techniques are on the same level as those of my average pair of shoes. Though I guess you are making up for it with your golem crafting skills.", "_t", true) -- 
tDef(84, "Change my name? I'm quite happy being 'Telos' thankyou. Though I wouldn't mind being 'Telos the Great and Powerful'. Do that actually. Yes!", "_t", true) -- 
tDef(91, "I'm a golem. How droll!\
Oh, did you want something?", "_t", true) -- 
tDef(99, "#LIGHT_GREEN#*The golem talks in a monotonous voice*#WHITE#\
Yes master.", "_t", true) -- 


