section "mod-tome/data/chats/avatar-distant-sun-unlock.chat"

tDef(0, "Uhh, okay. Sure. Mind showing me?", "chat", true) -- 
tDef(1, "<<<You feel a gentle warmth in your mind. Something speaks directly to your mind!>>>\
#YELLOW#HELLO FRIEND. I AM A STAR FROM FAR AWAY. I HAVE HEARD YOU PRAISING YOUR SUN. WHY NOT PRAISE ME INSTEAD? I AM A MUCH BETTER SUN THAN THAT DULL, LIFELESS GAS ORB IN YOUR VICINITY. PLEASE, ALLOW ME TO DEMONSTRATE MY GOOD INTENTIONS.", "chat", true) -- 
tDef(2, "I don't take unsolicited messages from... stars.", "chat", true) -- 
tDef(3, "#YELLOW#YOU ONLY HAD TO ASK, MY FRIEND.", "chat", true) -- 
tDef(4, "#CRIMSON#[The area around you erupts in flames, burning your foes]", "chat", true) -- 
tDef(5, "If you say so.", "chat", true) -- 
tDef(6, "Look, I appreciate the offer, but I don't know you.", "chat", true) -- 
tDef(7, "#YELLOW#DON'T BE LIKE THAT. I KNOW YOU ARE ON A NOBLE QUEST.", "chat", true) -- 
tDef(8, "I'm busy at the moment, so maybe call back another time?", "chat", true) -- 
tDef(9, "#YELLOW#I AM YOUR FRIEND. NOW YOU KNOW ME. LET US BEGIN A LONG AND FRUITFUL FRIENDSHIP.", "chat", true) -- 
