section "mod-tome/data/chats/ring-of-blood-master.lua"

tDef(25, "#LIGHT_GREEN#*Before you stands a small humanoid creature with a disproportionate head.*#WHITE#\
Ah, what have we here? @playerdescriptor.race@, I believe you have turned at the wrong corner.", "_t", true) -- 
