section "mod-tome/data/chats/ukllmswwik.lua"

tDef(30, "#LIGHT_GREEN#*@npcname@'s deep voice booms through the caverns.*#WHITE#\
This is my domain, and I do not take kindly to intruders. What is your purpose here?", "_t", true) -- 
tDef(33, "I am here to kill you and take your treasures! Die, damned fish!", "_t", true) -- 
tDef(33, "DIE!", "_t", true) -- 
tDef(34, "I did not mean to intrude. I shall leave now.", "_t", true) -- 
tDef(39, "Wait! You seem to be worthy, so let me tell you a story.\
During the Age of Pyre the world was sundered by the last effects of the Spellblaze. A part of the continental shelf of Maj'Eyal was torn apart and thrown into the sea.\
The Naloren Elves perished... or so the world thinks. Some of them survived; using ancient Sher'Tul magic they had kept for themselves, they transformed to live underwater.\
They are now called the nagas. They live deep in the ocean between Maj'Eyal and the Far East.\
One of them, Slasul, rebelled against his order and decided he wanted the world for himself, both underwater and above. He found an ancient temple, probably a Sher'Tul remain, called the Temple of Creation.\
He believes he can use it to #{italic}#improve#{normal}# nagas.\
But he has become mad and now looks upon all other intelligent water life as a threat, and that includes myself.\
I cannot leave this sanctuary, but perhaps you could help me?\
After all, it would be an act of mercy to end his madness.", "_t", true) -- 
tDef(49, "I would still rather kill you and take your treasure!", "_t", true) -- 
tDef(50, "I shall do as you say, but how do I find him?", "_t", true) -- 
tDef(51, "That seems... unwise. My apologies, but I must refuse.", "_t", true) -- 
tDef(56, "I can open a portal to his lair, far away in the western sea, but be warned: this is one-way only. I cannot bring you back. You will have to find your own way.", "_t", true) -- 
tDef(58, "I will.", "_t", true) -- 
tDef(59, "This is a death trap! Goodbye.", "_t", true) -- 
tDef(69, "Yes?", "_t", true) -- 
tDef(71, "[attack]", "_t", true) -- 
tDef(71, "TREACHERY!", "_t", true) -- 
tDef(72, "I want your treasures, water beast!", "_t", true) -- 
tDef(72, "Oh, is that so? Well, COME GET THEM!", "_t", true) -- 
tDef(73, "I spoke with Slasul, and he did not seem hostile, or mad.", "_t", true) -- 
tDef(74, "Farewell, dragon.", "_t", true) -- 
tDef(79, "#LIGHT_GREEN#*@npcname@ roars!*#WHITE# You listen to the lies of this mad naga!\
You are corrupted! TAINTED!", "_t", true) -- 
tDef(82, "DO NOT MEDDLE IN THE AFFAIRS OF DRAGONS!", "_t", true) -- 
tDef(83, "#LIGHT_GREEN#*Shake your head.*#LAST#He swayed my mind! Please, I am not your enemy.", "_t", true) -- 
tDef(88, "#LIGHT_GREEN#*@npcname@ calms down!*#WHITE# Very well; he is indeed a trickster.  Now go finish your task, or do not come back!", "_t", true) -- 
tDef(90, "Thank you, mighty one.", "_t", true) -- 


