section "mod-tome/data/chats/yeek-wayist.lua"

tDef(24, "#LIGHT_GREEN#*Before you stands a creature about as tall as a Halfling, covered in small white fur and with a disproportionate head.\
You also notice he does not wield his greatsword. It seems to float in the air, bound to his will.*#WHITE#\
Why did you save me, stranger? You are not of the Way.", "_t", true) -- 
tDef(28, "Well, you seemed to need help.", "_t", true) -- 
tDef(29, "So I could rip your throat myself!", "_t", true) -- 
tDef(34, "#LIGHT_GREEN#*The greatsword floats to a less aggressive stance. He seems surprised.*#WHITE#\
Then, on behalf of the Way, I thank you.", "_t", true) -- 
tDef(37, "What is the Way, and what are you?", "_t", true) -- 
tDef(42, "The Way is enlightenment, peace and protection. I am a Yeek. I came through this tunnel to explore this part of the world that was closed to us for centuries.", "_t", true) -- 
tDef(44, "Can you tell me more about the Way?", "_t", true) -- 
tDef(45, "Select the party member to receive the mental shield:", "_t", true) -- 
tDef(49, "The contact with the Wayist mind has improved your mental shields. (+15 mental save, +10%% confusion resistance)", "logPlayer", true) -- 
tDef(56, "I am never alone. I have the Way.", "_t", true) -- 
tDef(58, "Farewell, then.", "_t", true) -- 
tDef(63, "I cannot, but I may show you a glimpse.\
#LIGHT_GREEN#*He leans toward you. Your mind is suddenly filled with feelings of peace and happiness.*#WHITE#\
This is the Way.", "_t", true) -- 
tDef(67, "Thank you for this vision. Farewell, my friend.", "_t", true) -- 
tDef(79, "Thank the Way. This... thing... would have killed me.", "_t", true) -- 
tDef(81, "The Way sent me to explore this side of the tunnel.", "_t", true) -- 
tDef(86, "Yes, me too. We should split up to cover more ground.", "_t", true) -- 
tDef(88, "Farewell. We are the Way, always.", "_t", true) -- 


