tDef(145, "nightmare horror", "entity name", true) -- 
tDef(146, "A shifting form of darkest night that seems to reflect your deepest fears.", "_t", true) -- 
tDef(196, "headless horror", "entity name", true) -- 
tDef(197, "A headless, gangly humanoid with a large distended stomach.", "_t", true) -- 
