tDef(1064, "Ak'Gishil", "entity name", true) -- 
tDef(1065, "This Blade Horror has been infused with intense temporal magic, causing its power to increase dramatically. Rifts in space open around it constantly, summoning and banishing blades before vanishing as quickly as they appear.", "_t", true) -- 
