section "mod-tome/data/general/npcs/skeleton.lua"

tDef(24, "undead", "entity type", true) -- 
tDef(24, "skeleton", "entity subtype", true) -- 
tDef(59, "degenerated skeleton warrior", "entity name", true) -- 
tDef(60, "A haphazard collection of crumbling bones, with jerky movements that remind you of a child playing with a marionette.  It only has one arm, but that's all it needs to hold a sword.", "_t", true) -- 
tDef(69, "degenerated skeleton archer", "entity name", true) -- 
tDef(70, "A frail skeleton; just about the only bones that aren't cracked are its arms.  It's missing a hand, but a notch has been carved into its wrist to let it pull back a bowstring regardless.", "_t", true) -- 
tDef(83, "skeleton mage", "entity name", true) -- 
tDef(84, "Given its condition, you're less inclined to think this skeleton knows proper spells, rather than simply disgorging its magical energy as it breaks down.  This doesn't make it much less dangerous to be around, mind you.", "_t", true) -- 
tDef(103, "skeleton warrior", "entity name", true) -- 
tDef(104, "The forces binding this skeleton together are resilient enough to let it hold a shield and swing a weapon as well as it could have in life.  It's still wearing its old armor, in rusty but servicable condition.", "_t", true) -- 
tDef(115, "skeleton archer", "entity name", true) -- 
tDef(116, "Nobody scavenged the high-quality bow from this archer before it was raised from the dead.  You're about to wish the world had more grave-robbers.", "_t", true) -- 
tDef(129, "skeleton magus", "entity name", true) -- 
tDef(130, "This skeleton has been imbued with far more magical energy than normal, and serves as a conduit of its master's spellcasting prowess.", "_t", true) -- 
tDef(150, "armoured skeleton warrior", "entity name", true) -- 
tDef(151, "It feels no pain.  It moves with fluidity and strength that would tear natural muscles apart.  It must be from a fresh corpse, since its bones, armor, and weapon are all in pristine condition.  And it's furious.", "_t", true) -- 
tDef(176, "skeleton master archer", "entity name", true) -- 
tDef(177, "This skeleton can fire arrows and nock new ones with blinding speed.  Arcane forces pull its bones with unnatural precision - its arms will never tremble or get tired.", "_t", true) -- 
tDef(194, "skeleton assassin", "entity name", true) -- 
tDef(195, "Most skeletons announce their presence with a chorus of rattling bones; this one's been charred black and has enough cartilage between its joints to muffle its approach.  The first you'll see of it will be the flash of its blade.", "_t", true) -- 


