tDef(1252, "fur-lined leather wraps", "_t", true) -- 
tDef(1253, "Two large pieces of leather designed to be wrapped about the hands and the forearms.  This particular pair of wraps has been enchanted, imparting the wearer with great strength.", "_t", true) -- 
tDef(1278, "This would be great with a mighty matching belt.", "_t", true) -- 
