tDef(5825, "#RED#%s#GOLD# has been decapitated!#LAST#", "logSeen", true) -- 
tDef(5837, "Radiance", "entity name", true) -- 
tDef(5838, "a sparkling, golden cloak", "_t", true) -- 
tDef(5839, "This pristine golden cloak flows with a wind that seems to be conjured from nowhere. Its inner surface is a completely plain white, but the outside shines with intense light.", "_t", true) -- 
tDef(5865, "Unbreakable Greaves", "entity name", true) -- 
tDef(5866, "huge stony boots", "_t", true) -- 
tDef(5867, "These titanic boots appear to have been carved from stone. They appear weathered and cracked, but easily deflect all blows.", "_t", true) -- 
tDef(5893, "The Untouchable", "entity name", true) -- 
tDef(5894, "tough leather coat", "_t", true) -- 
tDef(5895, "This rugged jacket is the subject of many a rural legend.\
Some say it was fashioned by an adventurous mage turned rogue, in times before the Spellblaze, but was since lost.\
All manner of shady gamblers have since claimed to have worn it at one point or another. To fail, but live, is what it means to be untouchable, they said.", "_t", true) -- 
tDef(5917, "When you take a hit of more than 20% of your max life a shield is created equal to 130% the damage taken.", "_t", true) -- 
tDef(5927, "#LIGHT_BLUE#A barrier bursts from the leather jacket!", "logPlayer", true) -- 
tDef(5938, "Honeywood Chalice", "entity name", true) -- 
tDef(5939, "sap filled cup", "_t", true) -- 
tDef(5942, "This wooden cup seems perpetually filled with a thick sap-like substance. Tasting it is exhilarating, and you feel intensely aware when you do so.", "_t", true) -- 
tDef(5960, "The Calm", "entity name", true) -- 
tDef(5961, "ornate green robe", "_t", true) -- 
tDef(5962, "This green robe is engraved with icons showing clouds and swirling winds. Its original owner, a powerful mage named Proccala, was often revered for both his great benevolence and his intense power when it proved necessary.", "_t", true) -- 
tDef(5967, "Your Lightning and Chain Lightning spells gain a 24% chance to daze, and your Thunderstorm spell gains a 12% chance to daze.", "_t", true) -- 
tDef(5984, "Omniscience", "entity name", true) -- 
tDef(5985, "very plain leather cap", "_t", true) -- 
tDef(5990, "This white cap is plain and dull, but as the light reflects off of its surface, you see images of faraway corners of the world in the sheen.\"", "_t", true) -- 
tDef(6007, "reveal the surrounding area (range 20)", "_t", true) -- 
