tDef(6021, "strung clay beads", "_t", true) -- 
tDef(6022, "This is a string of ancient, hardened clay beads, cracked and faded with age. It was used by Wilders in ancient times, in an attempt to enhance their connection with Nature.", "_t", true) -- 
tDef(6028, "Enhances the effectiveness of Meditation by 20%", "_t", true) -- 
