tDef(6089, "gloomy black cloak", "_t", true) -- 
tDef(6090, "Forget the moons, the starry sky,\
The warm and greeting sheen of sun,\
The rays of light will never reach inside,\
The heart which wishes that it be unseen.", "_t", true) -- 
tDef(6129, "Spelldrinker", "entity name", true) -- 
tDef(6130, "eerie black dagger", "_t", true) -- 
tDef(6133, "Countless mages have fallen victim to the sharp sting of this blade, betrayed by those among them with greed for ever greater power.\
Passed on and on, this blade has developed a thirst of its own.", "_t", true) -- 
tDef(6146, "steals up to 50 mana from the target", "_t", true) -- 
tDef(6166, "Frost Lord's Chain", "entity name", true) -- 
