tDef(6296, "This impressive looking sword features two massive blades aligned in parallel. They seem weighted remarkably well.", "_t", true) -- 
tDef(6308, "25% chance to strike the target again.", "_t", true) -- 
tDef(6328, "Butcher", "entity name", true) -- 
tDef(6329, "blood drenched shortsword", "_t", true) -- 
tDef(6332, "Be it corruption, madness or eccentric boredom, the halfling butcher by the name of Caleb once took to eating his kin instead of cattle. His spree was never ended and nobody knows where he disappeared to. Only the blade remained, stuck fast in a bloodied block. Beneath, a carving said \"This was fun, let's do it again some time.\"", "_t", true) -- 
tDef(6341, "Enter Rampage if health falls below 20%%%s", "tformat", true) -- 
tDef(6341, " (cooling down: %d turns)", "tformat", true) -- 
tDef(6348, "Attempt to devour a low HP enemy, striking again and possibly killing it instantly.", "_t", true) -- 
tDef(6360, "Enter a Rampage (Shared cooldown).", "_t", true) -- 
tDef(6403, "Ethereal Embrace", "entity name", true) -- 
tDef(6404, "wispy purple cloak", "_t", true) -- 
tDef(6405, "This cloak waves and bends with shimmering light, reflecting the depths of space and the heart of the Aether.", "_t", true) -- 
tDef(6410, "Damage shields have +1 duration and +15% power", "_t", true) -- 
tDef(6435, "Boots of the Hunter", "entity name", true) -- 
tDef(6436, "well-worn boots", "_t", true) -- 
tDef(6437, "These cracked boots are caked with a thick layer of mud. It isn't clear who they previously belonged to, but they've clearly seen extensive use.", "_t", true) -- 
tDef(6478, "boost movement speed by 300% for up to 5 turns (or until you perform a non-movement action)", "_t", true) -- 
