tDef(6536, "Ring of the Archlich", "entity name", true) -- 
tDef(6537, "dusty, cracked ring", "_t", true) -- 
tDef(6538, "This ring is filled with an overwhelming, yet restrained, power. It lashes, grasps from its metal prison, searching for life to snuff out. You alone are unharmed.\
Perhaps it feels all the death you will bring to others in the near future.", "_t", true) -- 
tDef(6560, "#DARK_GREY#Your ring releases a burst of necromantic energy!", "logPlayer", true) -- 
