tDef(8024, "damp steel battle axe", "_t", true) -- 
tDef(8027, "The blade glows faintly blue, and reflects a sky full of stormy clouds.", "_t", true) -- 
tDef(8042, "inflicts either shocked or wet, chosen at random", "_t", true) -- 
