section "mod-tome/data/ingredients.lua"

tDef(24, "organic", "entity type", true) -- 
tDef(26, "length of troll intestine", "entity name", true) -- 
tDef(27, "A length of troll intestines. Fortunately, the troll appears to have eaten nothing in some time.", "_t", true) -- 
tDef(29, "Kindly empty it before returning.", "_t", true) -- 
tDef(35, "skeleton mage skull", "entity name", true) -- 
tDef(36, "The skull of a skeleton mage. The eyes have stopped glowing... for now.", "_t", true) -- 
tDef(38, "If the eyes are still glowing, please bash it around a bit until they fade. I'll not have another one of those coming alive and wreaking havoc in my lab.", "_t", true) -- 
tDef(44, "ritch stinger", "entity name", true) -- 
tDef(45, "A ritch stinger, still glistening with venom.", "_t", true) -- 
tDef(47, "Keep as much venom in it as possible.", "_t", true) -- 
tDef(53, "orc heart", "entity name", true) -- 
tDef(54, "The heart of an orc. Perhaps surprisingly, it isn't green.", "_t", true) -- 
tDef(56, "If you can fetch me a still-beating orc heart, that would be even better. But you don't look like a master necromancer to me.", "_t", true) -- 
tDef(62, "naga tongue", "entity name", true) -- 
tDef(63, "A severed naga tongue. It reeks of brine.", "_t", true) -- 
tDef(65, "Best results occur with tongues never tainted by profanity, so if you happen to know any saintly nagas...", "_t", true) -- 
tDef(71, "vial of greater demon bile", "entity name", true) -- 
tDef(72, "A vial of greater demon bile. It hurts your sinuses even with the vial's stopper firmly in place.", "_t", true) -- 
tDef(74, "Don't drink it, even if it tells you to.", "_t", true) -- 
tDef(80, "pouch of bone giant dust", "entity name", true) -- 
tDef(81, "Once the magics animating the bone giant fled, its remains crumbled to dust. It might be your imagination, but it looks like the dust occasionally stirs on its own.", "_t", true) -- 
tDef(83, "Never, ever to be confused with garlic powder. Trust me.", "_t", true) -- 
tDef(89, "ice ant stinger", "entity name", true) -- 
tDef(90, "Wickedly sharp and still freezing cold.", "_t", true) -- 
tDef(92, "If you've the means to eliminate the little venom problem, these make miraculous instant drink-chilling straws.", "_t", true) -- 
tDef(98, "minotaur nose", "entity name", true) -- 
tDef(99, "The severed front half of a minotaur snout, ring and all.", "_t", true) -- 
tDef(101, "You'll need to find one with a ring, preferably an expensive one.", "_t", true) -- 
tDef(107, "vial of elder vampire blood", "entity name", true) -- 
tDef(108, "Thick, clotted, and foul. The vial is cold to the touch.", "_t", true) -- 
tDef(110, "Once you've gotten it, cross some moving water on your way back.", "_t", true) -- 
tDef(116, "multi-hued wyrm scale", "entity name", true) -- 
tDef(117, "Beautiful and nearly impregnable. Separating it from the dragon must have been hard work.", "_t", true) -- 
tDef(119, "If you think collecting one of these is hard, try liquefying one.", "_t", true) -- 
tDef(125, "giant spider spinneret", "entity name", true) -- 
tDef(126, "An ugly, ripped-out chunk of giant spider. Bits of silk protrude from an orifice.", "_t", true) -- 
tDef(128, "The spiders in your barn won't do. You'll know a giant spider when you see one, though they're rare in Maj'Eyal.", "_t", true) -- 
tDef(134, "honey tree root", "entity name", true) -- 
tDef(135, "The severed end of one of a honey tree's roots. It wriggles around occasionally, seemingly unwilling to admit that it's dead... and a *plant*.", "_t", true) -- 
tDef(137, "Keep a firm grip on it. These things will dig themselves right back into the ground if you drop them.", "_t", true) -- 
tDef(143, "bloated horror heart", "entity name", true) -- 
tDef(144, "Diseased-looking and reeking. It seems to be decaying as you watch.", "_t", true) -- 
tDef(146, "Don't worry if it dissolves. Just don't get any on you.", "_t", true) -- 
tDef(152, "electric eel tail", "entity name", true) -- 
tDef(153, "Slimy, wriggling, and crackling with electricity.", "_t", true) -- 
tDef(155, "I know, I know. Where does the eel stop and the tail start? It doesn't much matter. The last ten inches or so should do nicely.", "_t", true) -- 
tDef(161, "vial of squid ink", "entity name", true) -- 
tDef(162, "Thick, black and opaque.", "_t", true) -- 
tDef(164, "However annoying this will be for you to gather, I promise that the reek it produces in my lab will prove even more annoying.", "_t", true) -- 
tDef(170, "bear paw", "entity name", true) -- 
tDef(171, "Large and hairy with flesh-rending claws. It smells slightly of fish.", "_t", true) -- 
tDef(173, "You'd think I could get one of these from a local hunter, but they've had no luck. Don't get eaten.", "_t", true) -- 
tDef(179, "ice wyrm tooth", "entity name", true) -- 
tDef(180, "This tooth has been blunted with age, but still looks more than capable of doing its job.", "_t", true) -- 
tDef(182, "Ice Wyrms lose teeth fairly often, so you might get lucky and not have to do battle with one. But dress warm just in case.", "_t", true) -- 
tDef(188, "red crystal shard", "entity name", true) -- 
tDef(189, "Tiny flames still dance ethereally inside this transparent crystal, though its heat seems to have faded... you hope.", "_t", true) -- 
tDef(191, "I hear these can be found in a cave near Elvala. I also hear that they can cause you to spontaneously combust, so no need to explain if you come back hideously scarred.", "_t", true) -- 
tDef(197, "vial of fire wyrm saliva", "entity name", true) -- 
tDef(198, "Clear and slightly thicker than water. It froths when shaken.", "_t", true) -- 
tDef(200, "Keep this stuff well away from your campfire unless you want me to have to find a new, more alive adventurer.", "_t", true) -- 
tDef(206, "chunk of ghoul flesh", "entity name", true) -- 
tDef(207, "Rotten and reeking. It still twitches occasionally.", "_t", true) -- 
tDef(209, "Unfortunately for you, the chunks that regularly fall off ghouls won't do. I need one freshly carved off.", "_t", true) -- 
tDef(215, "mummified bone", "entity name", true) -- 
tDef(216, "Bits of dry flesh still cling to this ancient bone.", "_t", true) -- 
tDef(218, "That is, a bone from a corpse that's undergone mummification. Actually, any bit of the body would do, but the bones are the only parts you're certain to find when you kick a mummy apart. I recommend finding one that doesn't apply curses.", "_t", true) -- 
tDef(224, "sandworm tooth", "entity name", true) -- 
tDef(225, "Tiny, dark grey, and wickedly sharp. It looks more like rock than bone.", "_t", true) -- 
tDef(227, "Yes, sandworms have teeth. They're just very small and well back from where you're ever likely to see them and live.", "_t", true) -- 
tDef(233, "black mamba head", "entity name", true) -- 
tDef(234, "Unlike the rest of the black mamba, the severed head isn't moving.", "_t", true) -- 
tDef(236, "If you get bitten, I can save your life if you still manage to bring back the head... and if it happens within about a minute from my door. Good luck.", "_t", true) -- 
tDef(242, "snow giant kidney", "entity name", true) -- 
tDef(243, "As unpleasant-looking as any exposed organ.", "_t", true) -- 
tDef(245, "I suggest not killing the snow giant by impaling it through the kidneys. You'll just have to find another.", "_t", true) -- 
tDef(251, "storm wyrm claw", "entity name", true) -- 
tDef(252, "Bluish and wickedly sharp. It makes your arm hair stand on end.", "_t", true) -- 
tDef(254, "I recommend severing one of their dewclaws. They're smaller and easier to remove, but they've never been blunted by use, so be careful you don't poke yourself. Oh yes, and don't get eaten.", "_t", true) -- 
tDef(260, "green worm", "entity name", true) -- 
tDef(261, "A dead green worm, painstakingly separated from its tangle of companions.", "_t", true) -- 
tDef(263, "Try to get any knots out before returning. Wear gloves.", "_t", true) -- 
tDef(269, "vial of wight ectoplasm", "entity name", true) -- 
tDef(270, "Cloudy and thick. Only by bottling it can you prevent it from evaporating within minutes.", "_t", true) -- 
tDef(272, "If you ingest any of this, never mind coming back here. Please.", "_t", true) -- 
tDef(278, "xorn fragment", "entity name", true) -- 
tDef(279, "Looks much like any other rock, though this one was recently sentient and trying to murder you.", "_t", true) -- 
tDef(281, "Avoid fragments that contained the xorn's eyes. You've no idea how unpleasant it is being watched by your ingredients.", "_t", true) -- 
tDef(287, "warg claw", "entity name", true) -- 
tDef(288, "Unpleasantly large and sharp for a canine's claw.", "_t", true) -- 
tDef(290, "My usual ingredient gatherers draw the line at hunting wargs. Feel free to mock them on your way back.", "_t", true) -- 
tDef(296, "pouch of faeros ash", "entity name", true) -- 
tDef(297, "Unremarkable grey ash.", "_t", true) -- 
tDef(299, "They're creatures of pure flame, and likely of extraplanar origin, but the ash of objects consumed by their fire has remarkable properties.", "_t", true) -- 
tDef(305, "wretchling eyeball", "entity name", true) -- 
tDef(306, "Small and bloodshot. Its dead gaze still burns your skin.", "_t", true) -- 
tDef(308, "Evil little things, wretchlings. Feel free to kill as many as you can, though I just need the one intact eyeball.", "_t", true) -- 
tDef(314, "faerlhing fang", "entity name", true) -- 
tDef(315, "It still drips venom and crackles with magical energy.", "_t", true) -- 
tDef(317, "I've lost a number of adventurers to this one, but I'm sure you'll be fine.", "_t", true) -- 
tDef(323, "vampire lord fang", "entity name", true) -- 
tDef(324, "Brilliantly white, but surrounded by blackest magic.", "_t", true) -- 
tDef(326, "You should definitely consider not pricking yourself with it.", "_t", true) -- 
tDef(332, "hummerhorn wing", "entity name", true) -- 
tDef(333, "Translucent and delicate-looking, but surprisingly durable.", "_t", true) -- 
tDef(335, "If you've not encountered hummerhorns before, they're like wasps, only gigantic and lethal.", "_t", true) -- 
tDef(341, "pouch of luminous horror dust", "entity name", true) -- 
tDef(342, "Weightless and glowing; not your usual dust.", "_t", true) -- 
tDef(344, "Not to be confused with radiant horrors. If you encounter the latter, then I suppose there are always more adventurers.", "_t", true) -- 


