section "mod-tome/data/quests/charred-scar.lua"

tDef(23, "The Doom of the World!", "_t", true) -- 
tDef(26, "You were sent to the Charred Scar at the heart of which lies a huge volcano. In the Age of Pyre it destroyed the old Sher'Tul ruins that stood there, absorbing much of their latent magic.", "_t", true) -- 
tDef(27, "This place is still full of that power and the orcs intend to absorb this power using the Staff of Absorption!", "_t", true) -- 
tDef(28, "Whatever their plan may be, they must be stopped at all cost.", "_t", true) -- 
tDef(29, "The volcano is attacked by orcs. A few Sun Paladins made it there with you. They will hold the line at the cost of their lives to buy you some time.", "_t", true) -- 
tDef(30, "Honor their sacrifice; do not let the orcs finish their work!", "_t", true) -- 
tDef(32, "", "_t", true) -- 
tDef(33, "You arrived too late. The place has been drained of its power and the sorcerers have left.", "_t", true) -- 
tDef(34, "Use the portal to go back to the Far East. You *MUST* stop them, no matter the cost.", "_t", true) -- 
tDef(37, "You arrived in time and interrupted the ritual. The sorcerers have departed.", "_t", true) -- 
tDef(72, "#VIOLET#A portal activates in the distance. You hear the orcs shout, 'The Sorcerers have departed! Follow them!'", "logPlayer", true) -- 
tDef(74, "#VIOLET#The Sorcerers flee through a portal. As you prepare to follow them, a huge faeros appears to block the way.", "logPlayer", true) -- 


