section "mod-tome/data/quests/deep-bellow.lua"

tDef(20, "From bellow, it devours", "_t", true) -- 
tDef(23, "Your escape from Reknor got your heart pounding and your desire for wealth and power increased tenfold.", "_t", true) -- 
tDef(24, "Maybe it is time for you to start an adventurer's career. Deep below the Iron Throne mountains lies the Deep Bellow.", "_t", true) -- 
tDef(25, "It has been long sealed away but still, from time to time adventurers go there looking for wealth.", "_t", true) -- 
tDef(26, "None that you know of has come back yet, but you did survive Reknor. You are great.", "_t", true) -- 


------------------------------------------------
section "mod-tome/data/quests/dreadfell.lua"

tDef(23, "The Island of Dread", "_t", true) -- 
tDef(26, "You have heard that near the Charred Scar, to the south, lies a ruined tower known as the Dreadfell.", "_t", true) -- 
tDef(27, "There are disturbing rumors of greater undead, and nobody who reached it ever returned.", "_t", true) -- 
tDef(28, "Perhaps you should explore it and find the truth, and the treasures, for yourself!", "_t", true) -- 


