section "mod-tome/data/quests/east-portal.lua"

tDef(20, "Back and there again", "_t", true) -- 
tDef(23, "You have created a portal back to Maj'Eyal. You should try to talk to someone in Last Hope about establishing a link back.", "_t", true) -- 
tDef(26, "You talked to the Elder in Last Hope who in turn told you to talk to Tannen, who lives in the north of the city.", "_t", true) -- 
tDef(30, "You gave the Orb of Many Ways to Tannen to study while you look for the athame and diamond in Reknor.", "_t", true) -- 
tDef(33, "You kept the Orb of Many Ways despite Tannen's request to study it. You must now look for the athame and diamond in Reknor.", "_t", true) -- 
tDef(36, "You brought back the diamond and athame to Tannen who asked you to check the tower of Telmur, looking for a text of portals, although he is not sure it is even there. He told you to come back in a few days.", "_t", true) -- 
tDef(39, "You brought back the diamond and athame to Tannen who asked you to contact Zemekkys to ask some delicate questions.", "_t", true) -- 
tDef(42, "You brought back the diamond and athame to Tannen who asked you to come back in a few days.", "_t", true) -- 
tDef(45, "Tannen has tricked you! He swapped the orb for a false one that brought you to a demonic plane. Find the exit, and get revenge!", "_t", true) -- 
tDef(48, "Tannen revealed himself as the vile scum he really is and trapped you in his tower.", "_t", true) -- 
tDef(52, "", "_t", true) -- 
tDef(53, "#LIGHT_GREEN#* The portal to the Far East is now functional and can be used to go back.#WHITE#", "_t", true) -- 
tDef(130, "Tannen points to the location of Telmur on your map.", "logPlayer", true) -- 
tDef(156, "A portal appears in the center of the tower!", "_t", true) -- 
tDef(173, "Meranas, Herald of Angolwen", "_t", true) -- 
tDef(187, "#VIOLET#You enter the swirling portal and in the blink of an eye you are back in Last Hope.", "logPlayer", true) -- 


