section "mod-tome/data/resources.lua"

tDef(45, "Air", "_t", true) -- 
tDef(45, "Air capacity in your lungs. Entities that need not breathe are not affected.", "_t", true) -- 
tDef(66, "Stamina", "_t", true) -- 
tDef(66, "Stamina represents your physical fatigue.  Most physical abilities consume it.", "_t", true) -- 
tDef(73, "Mana", "_t", true) -- 
tDef(73, "Mana represents your reserve of magical energies. Most spells cast consume mana and each sustained spell reduces your maximum mana.", "_t", true) -- 
tDef(80, "Equilibrium", "_t", true) -- 
tDef(80, "Equilibrium represents your standing in the grand balance of nature. The closer it is to 0 the more balanced you are. Being out of equilibrium will adversely affect your ability to use Wild Gifts.", "_t", true) -- 
