tDef(147, "Vim represents the amount of life energy/souls you have stolen. Each corruption talent requires some.", "_t", true) -- 
tDef(154, "Positive energy", "_t", true) -- 
tDef(154, "Positive energy represents your reserve of positive power. It slowly increases.", "_t", true) -- 
tDef(162, "Negative energy", "_t", true) -- 
tDef(162, "Negative energy represents your reserve of negative power. It slowly increases.", "_t", true) -- 
tDef(170, "Hate", "_t", true) -- 
tDef(170, "Hate represents your soul's primal antipathy towards others.  It generally decreases whenever you have no outlet for your rage, and increases when you are damaged or destroy others.", "_t", true) -- 
tDef(176, "Paradox", "_t", true) -- 
tDef(176, "Paradox represents how much damage you've done to the space-time continuum. A high Paradox score makes Chronomancy less reliable and more dangerous to use but also amplifies its effects.", "_t", true) -- 
