section "mod-tome/data/talents/celestial/chants.lua"

tDef(24, "Chant of Fortitude", "talent name", true) -- 
tDef(75, "You chant the glory of the Sun, granting you %d Mental Save and increasing your maximum life by %0.1f%% (Currently:  %d).\
\9\9You may only have one Chant active at once.\
\9\9The effects will increase with your Spellpower.", "tformat", true) -- 
tDef(84, "Chant of Fortress", "talent name", true) -- 
tDef(136, "You chant the glory of the Sun, granting you %d%% physical damage resistance, %d physical save, %d armour and +15%% armour hardiness.\
\9\9You may only have one Chant active at once.\
\9\9The effects will increase with your Spellpower.", "tformat", true) -- 
tDef(146, "Chant of Resistance", "talent name", true) -- 
tDef(216, "You chant the glory of the Sun, granting you %d%% fire, lightning, acid and cold damage resistance, %d spell save and reduces the damage from enemies 3 or more spaces away by %d%%.\
\9You may only have one Chant active at once.\
\9The effects will increase with your Spellpower.", "tformat", true) -- 
tDef(225, "Chant of Light", "talent name", true) -- 
tDef(261, "You chant the glory of the Sun, empowering your light and fire elemental attacks so that they do %d%% additional damage.\
\9\9In addition, this talent surrounds you with a shield of light, dealing %0.1f light damage to anything that hits you in melee.\
\9\9Your lite radius is also increased by %d.\
\9\9You may only have one Chant active at once and this Chant costs less power to sustain.\
\9\9The effects will increase with your Spellpower.", "tformat", true) -- 
tDef(272, "Chant Acolyte", "talent name", true) -- 
tDef(304, "You have learned to sing the praises of the Sun, in the form of three defensive Chants.\
\9\9\9Chant of Fortitude: Increases your mental save by %d and maximum life by %d%%.\
\9\9\9Chant of Fortress: Increases your physical save by %d, your physical resistance by %d%%, your armour by %d and your armour hardiness by 15%%.\
\9\9\9Chant of Resistance: Increases you spell save by %d, your fire/cold/lightning/acid resistances by %d%% and reduces all damage that comes from distant enemies (3 spaces or more) by %d%%.\
\9\9\9You may only have one Chant active at a time.", "tformat", true) -- 
tDef(321, "Chant Illuminate", "talent name", true) -- 
tDef(329, "Your Chants now bathe you in a cloak of light, which increases your stamina and mana regenerations by %0.2f per turn and does %0.2f light damage to anyone who hits you in melee.\
