section "mod-tome/data/talents/chronomancy/induced-phenomena.lua"

tDef(22, "Cosmic Cycle", "talent name", true) -- 
tDef(86, "#LIGHT_BLUE#Your cosmic cycle expands.", "logPlayer", true) -- 
tDef(105, "#LIGHT_RED#Your cosmic cycle contracts.", "logPlayer", true) -- 
tDef(143, "Tune yourself into the ebb and flow of spacetime.  When your Paradox crosses a 100 point threshold, your Cosmic Cycle gains or loses one radius.\
\9\9While Cosmic Cycle is expanding, your temporal resistance penetration will be increased by %d%%.  While it's contracting, your Willpower for Paradox calculations will be increased by %d%%.", "tformat", true) -- 
tDef(150, "Polarity Shift", "talent name", true) -- 
tDef(158, "You must have Cosmic Cycle active to use this talent.", "logPlayer", true) -- 
tDef(181, "Polarity Bolt", "_t", true) -- 
tDef(224, "Reverses the polarity of your Cosmic Cycle.  If it's currently contracting, it will begin to expand, firing a homing missile at each target within the radius that deals %0.2f temporal damage.\
\9\9If it's currently expanding, it will begin to contract, braiding the lifelines of all targets within the radius for %d turns.  Braided targets take %d%% of all damage dealt to other braided targets.\
\9\9The damage will scale with your Spellpower.", "tformat", true) -- 
tDef(231, "Reverse Causality", "talent name", true) -- 
tDef(273, "When a creature enters your expanding Cosmic Cycle, you heal %d life at the start of your next turn.\
\9\9When a creature leaves your contracting Cosmic Cycle, you reduce the duration of one detrimental effect on you by %d at the start of your next turn.\
\9\9The healing will scale with your Spellpower.", "tformat", true) -- 
tDef(280, "Epoch", "talent name", true) -- 
tDef(304, "%s resists the blindness!", "logSeen", true) -- 
tDef(310, "%s resists the pin!", "logSeen", true) -- 
tDef(316, "%s resists the confusion!", "logSeen", true) -- 
tDef(334, "While your cosmic cycle is expanding, creatures in its radius have a %d%% chance to suffer the effects of aging; pinning, blinding, or confusing them for 3 turns.\
\9\9While your cosmic cycle is contracting, creatures in its radius suffer from age regression; reducing their three highest stats by %d.\
\9\9The chance and stat reduction will scale with your Spellpower.", "tformat", true) -- 


