section "mod-tome/data/talents/chronomancy/other.lua"

tDef(22, "Spacetime Tuning", "talent name", true) -- 
tDef(101, "Spacetime Tuning", "_t", true) -- 
tDef(102, "What's your preferred paradox level?", "_t", true) -- 
tDef(120, "Use to set your preferred Paradox.  While resting or waiting you'll adjust your Paradox towards this number at the rate of %d per turn.\
\9\9Your Paradox modifier is factored into the duration and spellpower of all chronomancy spells.\
\
\9\9Preferred Paradox :  %d\
\9\9Paradox Modifier :  %d%%\
\9\9Spellpower for Chronomancy :  %d\
\9\9Willpower Paradox Modifier : -%d\
\9\9Paradox Sustain Modifier : +%d\
\9\9Total Modified Paradox :  %d\
\9\9Current Anomaly Chance :  %d%%", "tformat", true) -- 
tDef(135, "Slow", "talent name", true) -- 
tDef(174, "Creates a time distortion in a radius of %d that lasts for %d turns, decreasing global speed by %d%% for 3 turns and inflicting %0.2f temporal damage each turn to all targets within the area.\
\9\9The slow effect and damage dealt will scale with your Spellpower.", "tformat", true) -- 
tDef(181, "Spacetime Mastery", "talent name", true) -- 
tDef(198, "Your mastery of spacetime reduces the cooldown of Banish, Dimensional Step, Swap, and Temporal Wake by %d, and the cooldown of Wormhole by %d.  Also improves your Spellpower for purposes of hitting targets with chronomancy effects that may cause continuum destabilization (Banish, Time Skip, etc.), as well as your chance of overcoming continuum destabilization, by %d%%.", "tformat", true) -- 
tDef(205, "Quantum Feed", "talent name", true) -- 
tDef(230, "You've learned to boost your magic through your control over the spacetime continuum.  Increases your Magic and your Spell Save by %d.\
\9\9The effect will scale with your Willpower.", "tformat", true) -- 
tDef(236, "Moment of Prescience", "talent name", true) -- 
tDef(262, "You pull your awareness fully into the moment, increasing your stealth detection, see invisibility, defense, and accuracy by %d for %d turns.\
\9\9If you have Spin Fate active when you cast this spell, you'll gain a bonus to these values equal to 50%% of your spin.\
\9\9This spell takes no time to cast.", "tformat", true) -- 
tDef(270, "Gather the Threads", "talent name", true) -- 
tDef(286, "You begin to gather energy from other timelines. Your Spellpower will increase by %0.2f on the first turn and %0.2f more each additional turn.\
\9\9The effect ends either when you cast a spell, or after five turns.\
\9\9Eacn turn the effect is active, your Paradox will be reduced by %d.\
\9\9This spell will not break Spacetime Tuning, nor will it be broken by activating Spacetime Tuning.", "tformat", true) -- 
tDef(294, "Entropic Field", "talent name", true) -- 
tDef(318, "You encase yourself in a field that slows incoming projectiles by %d%%, and increases your physical resistance by %d%%.\
\9\9The effect will scale with your Spellpower.", "tformat", true) -- 
tDef(324, "Fade From Time", "talent name", true) -- 
tDef(341, "You partially remove yourself from the timeline for 10 turns.\
\9\9This increases your resistance to all damage by %d%%, reduces the duration of all detrimental effects on you by %d%%, and reduces all damage you deal by 20%%.\
\9\9The resistance bonus, effect reduction, and damage penalty will gradually lose power over the duration of the spell.\
\9\9The effects scale with your Spellpower.", "tformat", true) -- 
tDef(350, "Paradox Clone", "talent name", true) -- 
tDef(374, "Not enough space to summon!", "logPlayer", true) -- 
