tDef(431, "Displace Damage", "talent name", true) -- 
tDef(458, "#PINK##Source# displaces some damage onto #Target#!", "delayedLogMessage", true) -- 
tDef(474, "You bend space around you, displacing %d%% of any damage you receive onto a random enemy within range.\
