section "mod-tome/data/talents/cunning/lethality.lua"

tDef(20, "Lethality", "talent name", true) -- 
tDef(34, "You have learned to find and hit weak spots. All your strikes have a %0.1f%% greater chance to be critical hits, and your critical hits do %0.1f%% more damage.\
\9\9Also, when using knives and throwing knives, you now use your Cunning instead of your Strength for bonus damage.", "tformat", true) -- 
tDef(41, "Expose Weakness", "talent name", true) -- 
tDef(77, "Focus on a single target and perform a probing attack to find flaws in its defences, striking with your melee weapon(s) for %d%% damage.\
\9\9For %d turns thereafter, you gain %d armor penetration, %d accuracy, and %d%% all damage peneration.\
\9\9Learning this technique allows you to permanently gain %d armour penetration with all melee and archery attacks.\
\9\9The temporary armor penetration and accuracy bonuses increase with Cunning.", "tformat", true) -- 
tDef(86, "Blade Flurry", "talent name", true) -- 
tDef(137, "Become a whirling storm of blades, increasing attack speed by %d%% and causing melee attacks to strike an additional adjacent target other than your primary target for %d%% weapon damage. \
This talent is exhausting to use, draining 4 stamina each turn.", "tformat", true) -- 
tDef(143, "Snap", "talent name", true) -- 
tDef(175, "Your quick wits allow you to reset the cooldown of up to %d of your combat talents (cunning or technique) of tier %d or less.", "tformat", true) -- 


