section "mod-tome/data/talents/cunning/poisons.lua"

tDef(120, "Apply Poison", "talent name", true) -- 
tDef(163, "%s resists the vile poison!", "logSeen", true) -- 
tDef(187, "Learn how to coat your melee weapons, throwing knives, sling and bow ammo with poison, giving your attacks a %d%% chance to poison the target for %d nature damage per turn for %d turns. Every application of the poison stacks, up to a maximum of %d nature damage per turn.\
\9\9The damage scales with your Cunning.", "tformat", true) -- 
tDef(194, "Toxic Death", "talent name", true) -- 
tDef(215, "#GREEN#Poison bursts out of %s's corpse!", "logSeen", true) -- 
tDef(234, "When you kill a creature, all of your poisons affecting it will spread to foes in a radius of %d.", "tformat", true) -- 
tDef(239, "Vile Poisons", "talent name", true) -- 
tDef(275, "Learn how to enhance your Deadly Poison, adding additional effects. Each level, you will learn a new kind of poison enhancement:\
\9Level 1: Numbing Poison\
\9Level 2: Insidious Poison\
\9Level 3: Crippling Poison\
\9Level 4: Leeching Poison\
\9Level 5: Volatile Poison\
\9New poison enhancements can also be learned from special teachers in the world.\
\9Also increases the effectiveness of your poisons by %d%%. (The effect varies for each poison.)\
\9Adjusting your weapon coating takes no time and does not break stealth.\
\9You may only have two poison enhancements active at once; applying a third will randomly cause one of the existing ones to be cancelled.", "tformat", true) -- 
tDef(290, "Venomous Strike", "talent name", true) -- 
tDef(344, "#GREEN#%s's %s is disrupted by crippling poison!", "logSeen", true) -- 
tDef(378, "Numbing Poison - Reduces global speed by %d%% for 5 turns.\
\9\9Insidious Poison - Applies a standard poison that deals %0.2f nature damage over 5 turns.\
\9\9Crippling Poison - Places %d talents on cooldown for %d turns.\
\9\9Leeching Poison - Heals you for %d.\
\9\9Volatile Poison - Deals a further %0.2f nature damage to foes in a radius %d ball.\
\9\9", "tformat", true) -- 
tDef(389, "You strike your target with your melee or ranged weapon, doing %d%% weapon damage as nature and inflicting additional effects based on your active vile poisons:\
\9\9\
\9\9%s\
\9\9Learning this talent in addition to the Throwing Knives talent allows you to learn the Venomous Throw talent, which can be used to throw poisoned daggers at your foes, but is put on cooldown when this talent is used.\
\9\9", "tformat", true) -- 
tDef(403, "Numbing Poison", "talent name", true) -- 
tDef(429, "Enhances your Deadly Poison with a numbing agent, causing the poison to reduce all damage the target deals by %d%%.", "tformat", true) -- 
tDef(435, "Insidious Poison", "talent name", true) -- 
tDef(461, "Enhances your Deadly Poison with an insidious agent, causing it to reduce the healing taken by enemies by %d%%.", "tformat", true) -- 
tDef(467, "Crippling Poison", "talent name", true) -- 
tDef(493, "Enhances your Deadly Poison with a crippling agent, giving enemies a %d%% chance on using a talent to fail and lose a turn.", "tformat", true) -- 
tDef(499, "Leeching Poison", "talent name", true) -- 
tDef(525, "Enhances your Deadly Poison with a leeching agent, causing it to heal you for %d%% of the damage it does to its target.", "tformat", true) -- 
tDef(531, "Volatile Poison", "talent name", true) -- 
tDef(562, "Enhances your Deadly Poison with a volatile agent, causing the poison to deal %d%% increased damage to the victim and damage all of your enemies adjacent to it for 50%%.", "tformat", true) -- 
tDef(569, "Vulnerability Poison", "talent name", true) -- 
tDef(576, "Whenever you apply Deadly Poison, you also apply an unresistable magical poison dealing %0.2f arcane damage (based on your Magic) each turn. This poison reduces all damage resistance by 10%% and poison immunity by 50%%.", "tformat", true) -- 
tDef(583, "Stoning Poison", "talent name", true) -- 
tDef(636, "Enhance your Deadly Poison with a stoning agent.  Whenever you apply Deadly Poison, you afflict your target with an additional earth-based poison that inflicts %d nature damage per turn (stacking up to %d damage per turn) for %d turns.\
\9\9After either %d turns or the poison has run its course (<100%% chance, see effect description), the target will be turned to stone for %d turns.\
\9\9The damage scales with your Cunning.", "tformat", true) -- 


