section "mod-tome/data/talents/cunning/scoundrel.lua"

tDef(23, "Lacerating Strikes", "talent name", true) -- 
tDef(50, "Your melee and ranged attacks have a %d%% chance to shred enemies inflicting an additional 100%% of the damage dealt as a bleed over 4 turns.", "tformat", true) -- 
tDef(56, "Scoundrel's Strategies", "talent name", true) -- 
tDef(79, "#CRIMSON#%s's %s is disrupted by %s wounds!#LAST#", "logSeen", true) -- 
tDef(107, "Your melee and ranged attacks inflict distracting wounds that reduce the target’s critical strike multiplier by %d%% for 5 turns. \
In addition, your attacks have a %d%% chance to inflict a painful wound that causes them to forget a random talent for %d turns.  The last effect cannot occur more than once per turn per target.\
\9\9", "tformat", true) -- 
tDef(114, "Misdirection", "talent name", true) -- 
tDef(135, "#ORANGE#%s redirects the effect '%s'!#LAST#", "logSeen", true) -- 
tDef(153, "Your abilities in sowing confusion and chaos have reached their peak.  Whenever a foe attempts to apply a detrimental physical effect to you, they have a %d%% chance to fail. If there is an adjacent enemy to you, you misdirect your foe into applying it to them at %d%% duration.\
You gain %d defense.\
The chance to apply status effects increases with your Accuracy and the Defense with your Cunning.", "tformat", true) -- 
tDef(161, "Fumble", "talent name", true) -- 
tDef(183, "Your melee and ranged attacks leave your foes unable to focus on any complex actions, giving them a stacking 3%% chance of failure the next time they try to use a talent (to a maximum of %d%%).\
\9\9If any effect causes the target's turn to fail they fumble and injure themself, taking %0.2f physical damage.\
\9\9If the turn loss was caused by this effect then Fumble is removed.\
\9\9The damage dealt increases with your Cunning.\
\9\9", "tformat", true) -- 


