section "mod-tome/data/talents/cursed/fears.lua"

tDef(20, "Instill Fear", "talent name", true) -- 
tDef(69, "%s resists the fear!", "logSeen", true) -- 
tDef(85, "#F53CBE#%s resists the fear!", "logSeen", true) -- 
tDef(187, "Instill fear in your foes within %d radius of a target location dealing %0.2f mind and %0.2f darkness damage and causing one of 4 possible fears that last for %d turns.\
\9\9The targets can save vs your Mindpower to resist the effect.\
\9\9Fear effects improve with your Mindpower.\
\
\9\9Possible fears are:\
\9\9#ORANGE#Paranoid:#LAST# Gives the target an %d%% chance to physically attack a nearby creature, friend or foe. If hit, their target will be afflicted with Paranoia as well.\
\9\9#ORANGE#Despair:#LAST# Reduces mind resist, mindsave, armour and defence by %d.\
\9\9#ORANGE#Terrified:#LAST# Deals %0.2f mind and %0.2f darkness damage per turn and increases cooldowns by %d%%.\
\9\9#ORANGE#Haunted:#LAST# Causes the target to suffer %0.2f mind and %0.2f darkness damage for each detrimental mental effect every turn.\
\9\9", "tformat", true) -- 
tDef(206, "Heighten Fear", "talent name", true) -- 
tDef(230, "Heighten the fears of those near to you. Any foe you attempt to inflict a fear upon and who remains in a radius of %d and in sight of you for %d (non-consecutive) turns, will take %0.2f mind and %0.2f darkness damage and gain a new fear that lasts for %d turns.\
\9\9\9This effect completely ignores fear resistance, but can be saved against.", "tformat", true) -- 
tDef(237, "Tyrant", "talent name", true) -- 
tDef(252, "Impose your tyranny on the minds of those who fear you. When a foe gains a new fear, you have a %d%% chance to increase the duration of their heightened fear and one random existing fear effect by %d turns, to a maximum of 8 turns.\
\9\9Additionally, you gain %d Mindpower and Physical power for 5 turns every time you apply a fear, stacking up to %d times.", "tformat", true) -- 
tDef(258, "Panic", "talent name", true) -- 
tDef(283, "#F53CBE#%s ignores the panic!", "logSeen", true) -- 
tDef(287, "#F53CBE#%s resists the panic!", "logSeen", true) -- 
tDef(298, "Panic your enemies within a range of %d for %d turns. Anyone who fails to make a mental save against your Mindpower has a %d%% chance each turn of trying to run away from you.", "tformat", true) -- 


