section "mod-tome/data/talents/cursed/gestures.lua"

tDef(67, "Gesture of Pain", "talent name", true) -- 
tDef(106, "You require two free or mindstar-equipped hands to use Gesture of Pain.", "logPlayer", true) -- 
tDef(135, "%s resists the Gesture of Pain.", "logSeen", true) -- 
tDef(143, "#F53CBE#You revel in attacking a weakened foe! (+%d hate)", "logPlayer", true) -- 
tDef(201, "Use a gesture of pain in place of a normal attack to assault the minds of your enemies, inflicting between %0.1f and %0.1f mind damage. If the attack succeeds, there is a %d%% chance to stun your opponent for 3 turns.\
\9\9This strike replaces your melee physical and checks your Mindpower against your opponent's Mental Save, and is thus not affected by your Accuracy or the enemy's Defense. The base damage (doubled) and the critical chance of any Mindstars equipped are added in when this attack is performed.\
\9\9This talent requires two free or mindstar-equipped hands and has a 25%% chance to inflict brainlock, which can critically hit. The damage will increase with your Mindpower.\
\9\9If attacking with two mindstars the attack will trigger their proc effects, if any.\
\9\9Mindstars bonuses from damage and physical criticals: (+%d damage, +%d critical chance)", "tformat", true) -- 
tDef(211, "Gesture of Malice", "talent name", true) -- 
tDef(226, "Enhance your Gesture of Pain with a malicious curse that causes any victim that is struck to have all resistances lowered by %d%% for %d turns.\
\9\9", "tformat", true) -- 
tDef(232, "Gesture of Power", "talent name", true) -- 
tDef(251, "Enhance your mental attacks with a single gesture. You gain +%d mindpower and +%d%% chance to inflict critical damage with mind-based attacks (current chance is %d%%).\
\9\9Requires two free or mindstar-equipped hands; does not require Gesture of Pain to be sustained.", "tformat", true) -- 
tDef(257, "Gesture of Guarding", "talent name", true) -- 
tDef(291, "#F53CBE##Source# lashes back at #Target#!", "logCombat", true) -- 
tDef(304, "You guard against melee damage with a sweep of your hand. So long as you can use Gestures (Requires two free or mindstar-equipped hands), you deflect up to %d damage (%0.1f%% of your best free hand melee damage) from up to %0.1f melee attack(s) each turn (based on your cunning). Deflected attacks cannot be crits.\
\9\9If Gesture of Pain is active, you also have a %0.1f%% chance to counterattack.", "tformat", true) -- 


