tDef(25, "Predator", "talent name", true) -- 
tDef(57, "Improve your predation by learning from past hunts. You gain %0.2f accuracy and %0.2f armor penetration against foes for each foe of that type you have previously slain, to a maximum of %d accuracy and %d apr.", "tformat", true) -- 
