section "mod-tome/data/talents/cursed/rampage.lua"

tDef(20, "Rampage", "talent name", true) -- 
tDef(39, "You are already rampaging!", "logPlayer", true) -- 
tDef(90, "You enter a terrible rampage for %d turns (up to a maximum of %d turns), destroying everything in your path. Starting a rampage is instantaneous. You may also enter a rampage (50%% chance) when you are hit for more than 8%% of your max life. \
\9\9Any talent, rune or infusion you use while rampaging becomes a distraction, and reduces the duration of the rampage by 1. Your first movement while rampaging increases the rampage duration by 1.\
\9\9Rampage Bonus: +%d%% movement speed.\
\9\9Rampage Bonus: +%d%% attack speed.\
\9\9Rampage Bonus: +%d%% mind speed.", "tformat", true) -- 
tDef(99, "Brutality", "talent name", true) -- 
tDef(115, "You attack with mindless brutality. The first critical hit inflicted while rampaging increases the rampage duration by 1.\
\9\9Rampage Bonus: Your physical damage increases by %d%%.\
\9\9Rampage Bonus: Your Physical Save increases by %d and Mental Save increases by %d.", "tformat", true) -- 
tDef(122, "Tenacity", "talent name", true) -- 
tDef(140, "Nothing will stop your rampage.\
\9\9Rampage Bonus: You shrug off up to %d damage each turn during your rampage. If you shrug off more than %d damage, the rampage duration increases by 1.\
\9\9The amount of damage you can shrug off improves with your Strength.", "tformat", true) -- 
tDef(147, "Slam", "talent name", true) -- 
tDef(168, "You must be rampaging to use this talant.", "logPlayer", true) -- 
