tDef(350, "Rain of Spikes", "talent name", true) -- 
tDef(375, "Fires spikes all around you, making your foes within radius %d bleed for %0.2f damage over 6 turns.\
\9\9Damage and chance to apply the effect increase with Willpower.", "tformat", true) -- 


