section "mod-tome/data/talents/gifts/earthen-vines.lua"

tDef(20, "Stone Vines", "talent name", true) -- 
tDef(67, " and %0.1f Arcane", "tformat", true) -- 
tDef(68, "From the ground around you, you form living stone vines extending from your feet.\
\9\9Each turn, the vines will attempt to seize a random target within radius %d.\
\9\9Affected creatures are pinned to the ground and take %0.1f nature%s damage each turn for %d turns.\
\9\9A creature entangled by the vines will have a chance to break free each turn, and will automatically succeed if it is more than %d grids away from you.\
\9\9The chance to affect targets and damage increase with talent level and Willpower.", "tformat", true) -- 
tDef(78, "Eldritch Vines", "talent name", true) -- 
tDef(88, "Each time one of your stone vines deals damage to a creature it will restore %0.1f equilibrium and %0.1f mana.\
\9\9Your vines also become infused with eldritch energies, dealing an additional %0.1f arcane damage.", "tformat", true) -- 
tDef(95, "Rockwalk", "talent name", true) -- 
tDef(133, "Merge with one of your stone vines, traversing it to emerge near an entangled creature (maximum range %d).\
\9\9Merging with the stone is beneficial for you, healing %0.2f life (increases with Willpower).\
\9\9This will not break Body of Stone.", "tformat", true) -- 
tDef(141, "Rockswallow", "talent name", true) -- 
tDef(173, "Merge your target (within range %d) with one of your stone vines that has seized it, forcing it to traverse the vine and reappear near you.\
\9\9Merging with the stone is detrimental for the target, dealing %0.1f nature damage.\
\9\9The damage will increases with your Willpower.", "tformat", true) -- 


