section "mod-tome/data/talents/gifts/fire-drake.lua"

tDef(21, "Wing Buffet", "talent name", true) -- 
tDef(77, "You summon a powerful gust of wind, knocking back your foes within a radius of %d up to 3 tiles away and hitting them for %d%% weapon damage.\
\9\9Every level in Wing Buffet additionally raises your Physical Power and Accuracy by 2, passively.\
\9\9Each point in fire drake talents also increases your fire resistance by 1%%.\
\
\9\9This talent will also attack with your shield, if you have one equipped.", "tformat", true) -- 
tDef(86, "Bellowing Roar", "talent name", true) -- 
tDef(91, "@Source@ roars!", "_t", true) -- 
tDef(118, "You let out a powerful roar that sends your foes in radius %d into utter confusion (power: %d%%) for 3 turns.\
\9\9The sound wave is so strong, your foes also take %0.2f physical damage.\
\9\9The damage improves with your Strength.\
\9\9Each point in fire drake talents also increases your fire resistance by 1%%.", "tformat", true) -- 
tDef(126, "Devouring Flame", "talent name", true) -- 
tDef(173, "Spit a cloud of flames, doing %0.2f fire damage in a radius of %d each turn for %d turns.\
\9\9The flames will ignore the caster, and will drain 10%% of the damage dealt as the flames consume enemies life force and transfer it to the user.\
\9\9The damage will increase with your Mindpower, and can critical.\
\9\9Each point in fire drake talents also increases your fire resistance by 1%%.", "tformat", true) -- 
tDef(181, "Fire Breath", "talent name", true) -- 
tDef(188, "@Source@ breathes fire!", "_t", true) -- 
tDef(218, "You breathe fire in a frontal cone of radius %d. Any target caught in the area will take %0.2f fire damage over 3 turns.\
\9\9The damage will increase with your Strength and the critical chance is based on your Mental crit rate.\
\9\9Each point in fire drake talents also increases your fire resistance by 1%%.", "tformat", true) -- 


