section "mod-tome/data/talents/gifts/fungus.lua"

tDef(20, "Wild Growth", "talent name", true) -- 
tDef(37, "Surround yourself with a myriad of tiny, nearly invisible, reinforcing fungi.\
\9\9You gain %d maximum life and %d life regeneration.\
\9\9The effects will increase with your Willpower.", "tformat", true) -- 
tDef(45, "Fungal Growth", "talent name", true) -- 
tDef(58, "The fungus on your body allows regeneration effects to last longer.\
\9\9Each time you gain a beneficial effect with the regeneration subtype you increase its duration by %d%% + 1 rounded up.\
\9\9The effect will increase with your Mindpower.", "tformat", true) -- 
tDef(66, "Ancestral Life", "talent name", true) -- 
tDef(84, "#LIGHT_GREEN##Source# gains %d%%%% of a turn from Ancestral Life.#LAST#", "logCombat", true) -- 
tDef(100, "Your fungus reaches into the primordial ages of the world, granting you ancient instincts.\
\9\9Each time you receive non-regeneration healing you gain %0.1f%% of a turn per 100 life healed.  This effect can't add energy past 2 stored turns and overhealing is not counted.\
\9\9Also, regeneration effects on you will decrease your equilibrium by %0.1f each turn.\
\9\9The turn gain increases with your Mindpower.", "tformat", true) -- 
tDef(109, "Sudden Growth", "talent name", true) -- 
tDef(129, "A wave of energy passes through your fungus, making it release immediate healing energies on you, healing you for %d%% of your current life regeneration rate (#GREEN#%d#LAST#).", "tformat", true) -- 


