section "mod-tome/data/talents/gifts/harmony.lua"

tDef(20, "Waters of Life", "talent name", true) -- 
tDef(53, "The waters of life flow through you, purifying any poisons or diseases currently affecting you.\
\9\9For %d turns, all poisons and diseases will heal you instead of damaging you.\
\9\9When activated, it also heals you for %d life for each disease or poison you have.\
\9\9The healing per disease/poison will increase with your Willpower.", "tformat", true) -- 
tDef(62, "Elemental Harmony", "talent name", true) -- 
tDef(94, "Befriend the natural elements that constitute nature. Each time you are hit by one of the elements, you gain a special effect for %d turns. This can only happen every %d turns.\
\9\9Fire: +%d%% global speed\
\9\9Cold: +%d Armour\
\9\9Lightning: +%d to all stats\
\9\9Acid: +%0.2f life regen\
\9\9Nature: +%d%% to all resists", "tformat", true) -- 
tDef(105, "One with Nature", "talent name", true) -- 
tDef(137, "Commune with nature, removing the infusion saturation effect and reducing the cooldown of %d infusions by %d turns.", "tformat", true) -- 
tDef(143, "Healing Nexus", "talent name", true) -- 
tDef(174, "A wave of natural energies flow around you in a radius of %d.  All creatures in the area will be affected by the Healing Nexus effect for %d turns.\
\9\9On you, this effect causes each heal received to restore %d equilibrium and be %d%% effective.\
\9\9On other creatures, all healing is intercepted and redirected to you at %d%% efficiency.\
\9\9Only direct healing (not normal regeneration) is affected.", "tformat", true) -- 


