section "mod-tome/data/talents/gifts/moss.lua"

tDef(29, "Grasping Moss", "talent name", true) -- 
tDef(68, "Instantly grow a moss circle of radius %d at your feet.\
\9\9Each turn the moss deals %0.2f nature damage to each foe within its radius.\
\9\9This moss is very thick and sticky causing all foes passing through it have their movement speed reduced by %d%% and have a %d%% chance to be pinned to the ground for 4 turns.\
\9\9The moss lasts %d turns.\
\9\9Moss talents are instant but place all other moss talents on cooldown for 3 turns.\
\9\9The damage will increase with your Mindpower.", "tformat", true) -- 
tDef(79, "Nourishing Moss", "talent name", true) -- 
tDef(117, "Instantly grow a moss circle of radius %d at your feet.\
\9\9Each turn the moss deals %0.2f nature damage to each foe within its radius.\
\9\9This moss has vampiric properties and heals the user for %d%% of the damage done.\
\9\9The moss lasts %d turns.\
\9\9Moss talents are instant but place all other moss talents on cooldown for 3 turns.\
\9\9The damage will increase with your Mindpower.", "tformat", true) -- 
tDef(128, "Slippery Moss", "talent name", true) -- 
tDef(165, "Instantly grow a moss circle of radius %d at your feet.\
\9\9Each turn the moss deals %0.2f nature damage to each foe within its radius.\
\9\9This moss is very slippery and causes affected foes to have a %d%% chance of failing to perform complex actions.\
\9\9The moss lasts %d turns.\
\9\9Moss talents are instant but place all other moss talents on cooldown for 3 turns.\
\9\9The damage and the chance to apply the slippery effect increase with your Mindpower.", "tformat", true) -- 
tDef(176, "Hallucinogenic Moss", "talent name", true) -- 
tDef(215, "Instantly grow a moss circle of radius %d at your feet.\
\9\9Each turn the moss deals %0.2f nature damage to each foe within its radius.\
\9\9This moss is coated with strange fluids and has a %d%% chance to confuse (power %d%%) foes passing through it for 2 turns.\
\9\9The moss lasts %d turns.\
\9\9Moss talents are instant but place all other moss talents on cooldown for 3 turns.\
\9\9The damage will increase with your Mindpower.", "tformat", true) -- 


