section "mod-tome/data/talents/gifts/storm-drake.lua"

tDef(23, "Lightning Speed", "talent name", true) -- 
tDef(47, "You transform into pure lightning, moving %d%% faster for %d game turns.\
\9\9Also provides 30%% physical damage resistance and 100%% lightning resistance.\
\9\9Any actions other than moving will stop this effect.\
\9\9Note: since you will be moving very fast, game turns will pass very slowly.\
\9\9Levels in Lightning Speed additionally raises your Movement Speed by %d%%, passively.\
\9\9Each point in storm drake talents also increases your lightning resistance by 1%%.", "tformat", true) -- 
tDef(57, "Static Field", "talent name", true) -- 
tDef(85, "%s resists the static field!", "logSeen", true) -- 
tDef(89, "%s is caught in the static field!", "logSeen", true) -- 
tDef(102, "#PURPLE#%d STATIC#LAST#", "tformat", true) -- 
tDef(110, "Generate an electrical field around you in a radius of %d. Any creature caught inside will lose up to %0.1f%% of its current life (%0.1f%% if the target is Elite or Rare, %0.1f%% if the target is a Unique or Boss, and %0.1f%% if they are an Elite Boss.). This life drain is irresistable, but can be saved against with physical save.\
\9\9Additionally, it will deal %0.2f lightning damage afterwards, regardless of target rank.\
\9\9Current life loss and lightning damage will increase with your Mindpower, and the lightning damage element can critically hit with mental critical chances.\
\9\9Each point in storm drake talents also increases your lightning resistance by 1%%.", "tformat", true) -- 
tDef(118, "Tornado", "talent name", true) -- 
tDef(148, "Tornado", "_t", true) -- 
tDef(160, "%s is knocked back!", "logSeen", true) -- 
tDef(162, "%s resists the knockback!", "logSeen", true) -- 
tDef(194, "Summon a tornado that moves very slowly towards the target, following it if it changes position.\
\9\9Each time it moves every foes within radius 2 takes %0.2f lightning damage and is knocked back 2 spaces.\
\9\9When it reaches the target it explodes in a radius of %d, knocking back targets and dealing %0.2f lightning and %0.2f physical damage.\
\9\9The tornado will move a maximum of 20 times.\
\9\9Damage will increase with your Mindpower.\
\9\9Each point in storm drake talents also increases your lightning resistance by 1%%.", "tformat", true) -- 
tDef(204, "Lightning Breath", "talent name", true) -- 
tDef(211, "@Source@ breathes lightning!", "_t", true) -- 
tDef(239, "%s resists the stun!", "logSeen", true) -- 
tDef(256, "You breathe lightning in a frontal cone of radius %d. Any target caught in the area will take %0.2f to %0.2f lightning damage (%0.2f average) and be stunned for 3 turns.\
\9\9The damage will increase with your Strength, and the critical chance is based on your Mental crit rate, and the Stun apply power is based on your Mindpower.\
\9\9Each point in storm drake talents also increases your lightning resistance by 1%%.", "tformat", true) -- 


