section "mod-tome/data/talents/gifts/venom-drake.lua"

tDef(20, "Acidic Spray", "talent name", true) -- 
tDef(25, "@Source@ spits acid!", "_t", true) -- 
tDef(62, "Spray forth a glob of acidic moisture at your enemy.\
\9\9The target will take %0.2f Mindpower-based acid damage.\
\9\9Enemies struck have a 25%% chance to be Disarmed for three turns, as their weapon is rendered useless by an acid coating.\
\9\9At Talent Level 5, this becomes a piercing line of acid.\
\9\9Every level in Acidic Spray additionally raises your Mindpower by 4, passively.\
\9\9Each point in acid drake talents also increases your acid resistance by 1%%.", "tformat", true) -- 
tDef(72, "Corrosive Mist", "talent name", true) -- 
tDef(126, "Exhale a mist of lingering acid, dealing %0.2f acid damage that can critical in a radius of %d each turn for %d turns.\
\9\9Enemies in this mist will be corroded for %d turns, lowering their Accuracy, their Armour and their Defense by %d.\
\9\9The damage and duration will increase with your Mindpower, and the radius will increase with talent level.\
\9\9Each point in acid drake talents also increases your acid resistance by 1%%.", "tformat", true) -- 
tDef(134, "Dissolve", "talent name", true) -- 
tDef(178, "You strike the enemy with a rain of fast, acidic blows. You strike four times for pure acid damage. Every blow does %d%% damage.\
\9\9Every two talent levels, one of your strikes becomes blinding acid instead of normal acid, blinding the target 25%% of the time if it hits.\
\9\9Each point in acid drake talents also increases your acid resistance by 1%%.\
\
\9\9This talent will also attack with your shield, if you have one equipped.", "tformat", true) -- 
tDef(187, "Corrosive Breath", "talent name", true) -- 
tDef(194, "@Source@ breathes acid!", "_t", true) -- 
tDef(233, "You breathe acid in a frontal cone of radius %d. Any target caught in the area will take %0.2f acid damage.\
\9\9Enemies caught in the acid are disarmed for 3 turns.\
\9\9The damage will increase with your Strength, the critical chance is based on your Mental crit rate, and the Disarm apply power is based on your Mindpower.\
\9\9Each point in acid drake talents also increases your acid resistance by 1%%.", "tformat", true) -- 


