section "mod-tome/data/talents/misc/objects.lua"

tDef(19, "sher'tul", "talent category", true) -- 
tDef(19, "fortress", "talent type", true) -- 
tDef(19, "Yiilkgur abilities.", "_t", true) -- 
tDef(20, "spell", "talent category", true) -- 
tDef(20, "object spells", "talent type", true) -- 
tDef(20, "Spell abilities of the various objects of the world.", "_t", true) -- 
tDef(21, "other", "talent category", true) -- 
tDef(21, "object powers", "talent type", true) -- 
tDef(21, "Abilities of the various objects of the world.", "_t", true) -- 
tDef(22, "technique", "talent category", true) -- 
tDef(22, "object techniques", "talent type", true) -- 
tDef(22, "Techniques of the various objects of the world.", "_t", true) -- 
tDef(23, "wild-gift", "talent category", true) -- 
tDef(23, "Wild gifts of the various objects of the world.", "_t", true) -- 
tDef(24, "misc", "talent category", true) -- 
tDef(24, "Powers of the various objects of the world.", "_t", true) -- 
tDef(30, "charms", "talent name", true) -- 
tDef(46, "Arcane Supremacy", "talent name", true) -- 
tDef(103, "Removes up to %d detrimental magical effects and empowers you with arcane energy for ten turns, increasing spellpower and spell save by 5 plus 5 per effect removed.", "tformat", true) -- 
tDef(109, "Attune Mindstar", "talent name", true) -- 
tDef(116, "@Source@ refocuses the energies of %s mindstar.", "tformat", true) -- 
tDef(123, "You attune your %s to deal #ORANGE#mind#LAST# damage.", "logPlayer", true) -- 
tDef(126, "You attune your %s to deal #LIGHT_GREEN#nature#LAST# damage.", "logPlayer", true) -- 
tDef(137, "Alter the flow of energies of your equiped mindstars, changing their damage type between nature and mind.", "tformat", true) -- 
tDef(142, "Command Staff", "talent name", true) -- 
tDef(149, "@Source@ refocuses the energies of %s staff.", "tformat", true) -- 
tDef(166, "You need a staff.", "logPlayer", true) -- 
tDef(170, "You must be holding a staff.", "logPlayer", true) -- 
tDef(198, "Alter the flow of energies through a staff.", "tformat", true) -- 
tDef(204, "Ward", "talent name", true) -- 
tDef(215, "Ward", "_t", true) -- 
tDef(231, "Bring a damage-type-specific ward into being. The ward will fully negate as many attacks of its element as it has charges.\
\9\9You can activate the following wards: %s", "tformat", true) -- 
tDef(237, "Teleport to the ground", "talent name", true) -- 
tDef(245, "Use Yiilkgur's teleporter to teleport to the ground.", "tformat", true) -- 
tDef(250, "Block", "talent name", true) -- 
tDef(261, "You require a shield to use this talent.", "logPlayer", true) -- 
tDef(304, "None", "_t", true) -- 
tDef(313, " and ", "_t", true) -- 
tDef(329, " Increases your spell save by %d for that turn.", "tformat", true) -- 
tDef(332, " Reflects all blocked damage back to the source.", "_t", true) -- 
tDef(335, " All blocked damage heals the wielder.", "_t", true) -- 
tDef(338, "Raise your shield into blocking position for 2 turns reducing all non-Mind damage by %d. If you block all of an attack's damage, the attacker will be vulnerable to a deadly counterstrike (the next weapon attack will instead deal 200%% damage) for one turn.\
\9\9\9Counterstrike can normally only effect one enemy per block.\
\9\9\9If any damage was successfully blocked this effect will be removed at the start of your turn.\
\9\9\9If the shield has damage resistance to the blocked damage type the block value is increased by 50%%.\
\9\9\9\
\9\9\9Current Bonuses:  %s%s%s%s", "tformat", true) -- 
tDef(350, "Bloom Heal", "talent name", true) -- 
tDef(362, "Call upon the power of nature to regenerate your body for %d life every turn for 6 turns.\
\9\9The life healed will increase with the Willpower stat.", "tformat", true) -- 
tDef(369, "Destroy Magic", "talent name", true) -- 
tDef(424, "%s's animating magic is disrupted!", "logSeen", true) -- 
tDef(431, "The target has a %d%% chance (stacking to a maximum of %d%%) to fail to cast any spell.  At level 2 magical effects may be disrupted, at level 3 magical sustains may be disrupted, and at level 5 magical constructs and undead may be stunned.", "tformat", true) -- 
tDef(436, "Battle Trance", "talent name", true) -- 
tDef(461, "You overdose on the honeyroot sap!", "logPlayer", true) -- 
tDef(467, "You enter into a fighting trance, gaining 15%% resist all, losing 15 mindpower, but gaining 20 mental save. However, each turn after the fifth that this talent is active, there is a chance that you will be overcome and become confused.\
This does not take a turn to use.", "tformat", true) -- 
tDef(473, "Soul Purge", "talent name", true) -- 
tDef(488, "Remove any talent Morrigor has absorbed.", "tformat", true) -- 
tDef(493, "Dig", "talent name", true) -- 
tDef(511, "You require a digger to dig.", "logPlayer", true) -- 
tDef(520, "digging", "_t", true) -- 
tDef(520, "dug", "_t", true) -- 
tDef(526, "You have been interrupted!", "logPlayer", true) -- 
tDef(539, "Dig/cut a tree/...\
\9\9Digging takes %d turns (based on your currently best digger available).", "tformat", true) -- 
tDef(545, "Shivgoroth Form", "talent name", true) -- 
tDef(558, "You are already a Shivgoroth!", "logPlayer", true) -- 
tDef(567, "You absorb latent cold around you, turning into an ice elemental - a shivgoroth - for %d turns.\
\9\9While transformed, you do not need to breathe, gain access to the Ice Storm talent at level %d, gain %d%% resistance to cuts and stuns, gain %d%% cold resistance, and all cold damage heals you for %d%% of the damage done.\
\9\9The power will increase with your Spellpower.", "tformat", true) -- 
tDef(575, "Mental Refresh", "talent name", true) -- 
tDef(604, "Reset up to 3 wild gift, psionic or cursed talents.", "tformat", true) -- 
tDef(609, "Dagger Block", "talent name", true) -- 
tDef(669, "Raise your dagger into blocking position for one turn, reducing the damage of all physical melee attacks against you by %d. If you block all of an attack's damage, the attacker will be vulnerable to a deadly counterstrike (a normal attack will instead deal 200%% damage) for one turn and be left disarmed for 3 turns.\
\9\9The blocking value will increase with your Dexterity and Cunning.", "tformat", true) -- 
tDef(675, "Shieldsmaiden Aura", "talent name", true) -- 
tDef(684, "#CRIMSON#%s's shield deflects the blow!", "logSeen", true) -- 
tDef(691, "Can block up to 1 hit per 10 turns.", "tformat", true) -- 
tDef(696, "Psionic Maelstrom", "talent name", true) -- 
tDef(720, "For the next 8 turns, powerful blasts of psionic energies will erupt from you, doing %d damage.", "tformat", true) -- 
tDef(732, "Melee retaliation", "talent name", true) -- 
tDef(737, "Intermediary for melee retaliation.", "tformat", true) -- 


