section "mod-tome/data/talents/misc/races.lua"

tDef(37, "race", "talent category", true) -- 
tDef(37, "higher", "talent type", true) -- 
tDef(37, "The various racial bonuses a character can have.", "_t", true) -- 
tDef(41, "Wrath of the Highborn", "talent name", true) -- 
tDef(54, "Call upon the power of the Highborn, increasing all damage by %d%% and reducing all damage taken by %d%% for 5 turns.\
\9\9The bonus will increase with your Magic.", "tformat", true) -- 
tDef(61, "Overseer of Nations", "talent name", true) -- 
tDef(81, "While Highers are not meant to rule other humans - and show no particular will to do so - they are frequently called to higher duties.\
\9\9Their nature grants them better senses than other humans.\
\9\9Increase blindness immunity by %d%%, maximum sight range by %d, and increases existing infravision, and heightened senses range by %d.\
\9\9At talent level 5, each time you hit a target you gain telepathy to all similar creatures in radius 15 for 5 turns.", "tformat", true) -- 
tDef(90, "Born into Magic", "talent name", true) -- 
tDef(108, "Highers were originally created during the Age of Allure by the human Conclave. They are imbued with magic at the very core of their being.\
\9\9Increase spell save by %d and arcane resistance by %d%%.\
\9\9Also, when you cast a spell dealing damage, you gain a 20%% bonus to the damage type for 5 turns. (This effect has a cooldown.)", "tformat", true) -- 
tDef(116, "Highborn's Bloom", "talent name", true) -- 
tDef(155, "Activate some of your inner magic, using it to power your abilities.  For the next %d turns all active talents will be used without resource cost.\
\9\9Your resources must still be high enough to initially power the talent and failure rates (etc.) still apply.\
\9\9", "tformat", true) -- 
tDef(164, "shalore", "talent type", true) -- 
tDef(167, "Grace of the Eternals", "talent name", true) -- 
tDef(180, "Call upon the grace of the Eternals to increase your global speed by %d%% for 5 turns.\
\9\9The speed bonus will increase with your Dexterity or Magic (whichever is higher).", "tformat", true) -- 
tDef(187, "Magic of the Eternals", "talent name", true) -- 
tDef(199, "Reality bends slightly in the presence of a Shaloren due to their inherent magical nature.\
\9\9Increases critical chance by %d%% and critical strike power by %d%%.", "tformat", true) -- 
tDef(206, "Secrets of the Eternals", "talent name", true) -- 
tDef(232, "As the only immortal race of Eyal, Shaloren have learnt over the long years to use their innate inner magic to protect themselves.\
\9\9%d%% chance to become invisible (power %d) for 5 turns when hit by a blow doing at least 10%% of your total life.", "tformat", true) -- 
tDef(239, "Timeless", "talent name", true) -- 
tDef(300, "The world grows old as you stand through the ages. To you, time is different.\
\9\9Reduces the time remaining on detrimental effects by %d, most cooling down talents by %d, and increases the time remaining on beneficial effects by %d (up to 2 times the current duration).", "tformat", true) -- 
tDef(309, "thalore", "talent type", true) -- 
tDef(312, "Gift of the Woods", "talent name", true) -- 
tDef(328, "Call upon nature to regenerate your body for %d life every turn and increase healing mod by %d%% for 8 turns.\
\9\9The life healed will increase with your Willpower or Constitution (whichever is higher).", "tformat", true) -- 
tDef(334, "Verdant", "talent name", true) -- 
tDef(348, "Thaloren have an affinity for natural elements, allowing them to heal for a portion of damage taken from them.\
\9\9You gain %d%% Nature and Acid damage affinity.", "tformat", true) -- 
tDef(355, "Guardian of the Wood", "talent name", true) -- 
tDef(369, "Thaloren are part of the wood; it shields them from corruption.\
\9\9Increase disease immunity by %d%%, blight resistance by %0.1f%%, and all resistances by %0.1f%%.", "tformat", true) -- 
tDef(376, "Nature's Pride", "talent name", true) -- 
tDef(396, "Not enough space to summon!", "logPlayer", true) -- 
tDef(404, "treant", "_t", true) -- 
tDef(406, "A very strong near-sentient tree.", "_t", true) -- 
tDef(450, "Nature is with the Thaloren; they can always feel the call of the woods.\
\9\9Summons two elite Treants to your side for 8 turns.\
\9\9The treants have a global resistance equal to your blight resistance and can stun, knockback, and taunt foes.\
\9\9Your Willpower (%d) will be added to all of their non-Magic primary stats and their talent levels will increase with your Nature's Pride talent level.\
\9\9Your increased damage, damage penetration, and many other stats will be inherited.", "tformat", true) -- 
tDef(461, "dwarf", "talent type", true) -- 
tDef(464, "Resilience of the Dwarves", "talent name", true) -- 
tDef(485, "Call upon the legendary resilience of the Dwarven race to increase armour (+%d), armour hardiness (+%d%%), spell (+%d) and physical (+%d) saves for 8 turns.\
\9\9The bonuses will increase with your Constitution.", "tformat", true) -- 
tDef(492, "Stoneskin", "talent name", true) -- 
tDef(502, "Dwarf skin is a complex structure; it can automatically react to physical blows and harden itself.\
\9\9When you are hit in melee, you have a 15%% chance to increase your armour total by %d for 5 turns and fully ignore the attack triggering it.\
\9\9There is no cooldown to this effect; it can happen while already active.", "tformat", true) -- 
tDef(510, "Power is Money", "talent name", true) -- 
tDef(522, "Money is the heart of the Dwarven Empire; it rules over all other considerations.\
\9\9Increases Physical, Mental and Spell Saves based on the amount of gold you possess.\
\9\9+1 save every %d gold, up to +%d. (currently +%d)", "tformat", true) -- 
tDef(530, "Stone Walking", "talent name", true) -- 
tDef(560, "While the origins of the dwarves remain clouded in mystery to the other races, it is obvious that they share strong ties to the stone.\
\9\9You can target any wall and immediately enter it, appearing on the other side.\
\9\9This can pass through up to %d tiles (increases with Constitution and talent level).", "tformat", true) -- 
tDef(570, "halfling", "talent type", true) -- 
tDef(573, "Luck of the Little Folk", "talent name", true) -- 
tDef(592, "Call upon the luck and cunning of the Little Folk to increase your critical strike chance by %d%% and your saves by %d for 5 turns.\
\9\9The bonus will increase with your Cunning.", "tformat", true) -- 
tDef(599, "Duck and Dodge", "talent name", true) -- 
tDef(616, "Halfling's incredible luck always kicks in at just the right moment to save their skin.\
\9\9Whenever you take %d%% or more of your life from a single attack, you gain %d%% Evasion and %d additional defense for the next %d turns. The defense increases based on your luck and other defensive stats.", "tformat", true) -- 
tDef(623, "Militant Mind", "talent name", true) -- 
tDef(629, "Halflings have always been a very organised and methodical race; the more foes they face, the more organised they are.\
\9\9If two or more foes are in sight your Physical Power, Physical Save, Spellpower, Spell Save, Mental Save, and Mindpower are increased by %0.1f per foe (up to 5 foes).", "tformat", true) -- 
tDef(636, "Indomitable", "talent name", true) -- 
tDef(691, "Halflings have one of the most powerful military forces in the known world and have been at war with most other races for thousands of years.\
\9\9Removes %d stun, daze, or pin effects and grants immunity to stuns, dazes and pins for %d turns.", "tformat", true) -- 
tDef(699, "orc", "talent type", true) -- 
tDef(702, "Orcish Fury", "talent name", true) -- 
tDef(735, "Summons your lust for blood and destruction; especially when the odds are against you.  \
\9\9You increase your damage by 10%% + %0.1f%% per enemy you can see in line of sight of you (maximum 5 enemies, %0.1f%% bonus) for 3 turns.\
\9\9The damage bonus will increase with your Constitution.", "tformat", true) -- 
tDef(743, "Hold the Ground", "talent name", true) -- 
tDef(760, "#CRIMSON#%s roars with rage shaking off %d mental debuffs!", "logSeen", true) -- 
tDef(765, "Orcs have been the prey of the other races for thousands of years, with or without justification. They have learnt to withstand things that would break weaker races.\
\9\9When your life goes below 50%% your sheer determination cleanses you of %d mental debuff(s) based on talent level and Willpower.  This can only happen once every %d turns.\
\9\9Also increases physical save by %d.", "tformat", true) -- 
tDef(773, "Skirmisher", "talent name", true) -- 
tDef(788, "Orcs have seen countless battles, and won many of them.\
\9\9You revel in the defeat of your foes, gaining %d%% damage resistance for 2 turns each time you kill an enemy.\
\9\9The resistance will scale with talent level and your Constitution.\
\9\9Additionally, passively increase all damage penetration by %d%%.", "tformat", true) -- 
tDef(797, "Pride of the Orcs", "talent name", true) -- 
tDef(848, "Call upon the will of all of the Orc Prides to survive this battle.\
\9\9You remove up to %d detrimental effect(s) then heal for %d life.\
\9\9The healing will increase with talent level and your Willpower.", "tformat", true) -- 
tDef(859, "yeek", "talent type", true) -- 
tDef(862, "Dominant Will", "talent name", true) -- 
tDef(881, "%s is immune to instakill and mind control effects!", "logSeen", true) -- 
tDef(885, "%s must be below 80%% of their max life to be controlled!", "logSeen", true) -- 
tDef(900, "%s resists the mental assault!", "logSeen", true) -- 
tDef(907, "Shatter the mind of your victim, giving you full control of its actions for %s turns (based on your Willpower).\
\9When the effect ends, you pull out your mind and the victim's body collapses, dead.\
\9Targets with ranks at or above rare must be below 80%% of their maximum life to be controlled, will be invulnerable for the duration, and will break free of the effect without dying after 3 turns.\
\9This effect cannot be saved against but checks instakill immunity.", "tformat", true) -- 
tDef(915, "Unity", "talent name", true) -- 
tDef(928, "Your mind becomes more attuned to the Way, and is shielded from outside effects.\
\9\9Increase confusion and silence immunities by %d%% and Mental Save by %d.", "tformat", true) -- 
tDef(935, "Quickened", "talent name", true) -- 
tDef(950, "#RED#%s reacts immediately after taking severe wounds!#LAST#", "logSeen", true) -- 
tDef(955, "Yeeks live fast, think fast, and sacrifice fast for the Way.\
\9\9Your global speed is increased by %0.1f%%.\
\9\9If your life is below 30%% after taking damage you gain 1.5 turns.  This effect can only happen once every %d turns.", "tformat", true) -- 
tDef(962, "Wayist", "talent name", true) -- 
tDef(990, "yeek mindslayer", "_t", true) -- 
tDef(992, "A wayist that came to help.", "_t", true) -- 
tDef(1047, "Reach through the collective psionic gestalt of the yeeks, the Way, to call for immediate help.\
\9\9Summons up to 3 yeek mindslayers to your side for 6 turns.\
\9\9All their primary stats will be set to %d (based on your Willpower and Talent Level).\
\9\9Your increased damage, damage penetration, and many other stats will be inherited.", "tformat", true) -- 
tDef(1057, "Knowledge of the Way", "talent name", true) -- 
tDef(1064, "You merge your mind with the rest of the Way for a brief moment; the sum of all yeek knowledge gathers in your mind\
\9\9and allows you to identify any item you could not recognize yourself.", "tformat", true) -- 
tDef(1072, "ogre", "talent type", true) -- 
tDef(1075, "Ogric Wrath", "talent name", true) -- 
tDef(1092, "You enter an ogric wrath for %d turns, increasing your stun and pinning resistances by 20%% and all damage done by 10%%.\
\9\9In addition, whenever you use an infusion or rune, miss a melee attack, or any damage you deal is reduced by a damage shield (or similar effect) you gain a charge of Ogre Fury (up to 5 charges total, each lasting 7 turns).\
\9\9Each charge grants 20%% critical damage power and 5%% critical strike chance.\
\9\9You lose a charge each time you deal a critical strike.\
\9\9The duration will increase with your Strength.", "tformat", true) -- 
tDef(1101, "Grisly Constitution", "talent name", true) -- 
tDef(1120, "An ogre's body is acclimated to spells and inscriptions.\
\9\9Increases spell save by %d and improves the contribution of primary stats on infusions and runes by %d%%.\
\9\9At level 5 your body is so strong you can use a two handed weapon in your main hand while still using an offhand item.\
\9\9When using a two handed weapon this way you suffer a 20%% accuracy, physical power, spellpower and mindpower penalty, decreasing by 5%% per size category above #{italic}#big#{normal}#; further, all damage procs from your weapons are reduced by 50%%.", "tformat", true) -- 
tDef(1129, "Scar-Scripted Flesh", "talent name", true) -- 
tDef(1155, "When you crit you have a %d%% chance to reduce by 1 the remaining cooldown of one of your inscriptions and of any saturations effects.\
\9\9This effect can only happen once per turn.", "tformat", true) -- 
tDef(1162, "Writ Large", "talent name", true) -- 
tDef(1173, "#PURPLE#Your mastery over inscriptions is unmatched! One more inscriptions slot available to buy.", "logPlayer", true) -- 
tDef(1184, "Instantly removes runic and infusion saturations.\
\9\9For %d turns your inscriptions cool down twice as fast.\
\9\9At level 5 your command over inscriptions is so good that you can use one more (you still need a category point to unlock it; you need to exit the levelup screen to validate it).", "tformat", true) -- 


