section "mod-tome/data/talents/psionic/augmented-striking.lua"

tDef(23, "Kinetic Strike", "talent name", true) -- 
tDef(41, "You cannot do that without a weapon in your hands.", "logPlayer", true) -- 
tDef(55, "%s resists the pin!", "logSeen", true) -- 
tDef(101, "Focus kinetic energy and strike an enemy for %d%% weapon damage as physical.\
\9\9They will be pinned to the ground for %d turns by the force of this attack.\
\9\9Any frozen creature hit by this attack will take an extra %0.2f physical damage.\
\9\9The extra damage will scale with your Mindpower.", "tformat", true) -- 
tDef(111, "Thermal Strike", "talent name", true) -- 
tDef(156, "ice wall", "_t", true) -- 
tDef(157, "a summoned, transparent wall of ice", "_t", true) -- 
tDef(199, "Focus thermal energy and strike an enemy for %d%% weapon damage as cold.\
\9\9A burst of cold will then engulf them, doing an extra %0.1f Cold damage and also freeze them for %d turns.\
\9\9If the attack freezes a pinned creature a burst of ice is summoned, circling the caster and the creature with a wall of ice for 3 turns.\
\9\9The cold burst damage will scale with your Mindpower.", "tformat", true) -- 
tDef(208, "Charged Strike", "talent name", true) -- 
tDef(314, "Focus charged energy and strike an enemy for %d%% weapon damage as lightning.\
\9\9Energy will then discharge from your weapon, doing an extra %0.2f lightning damage and halving their stun/daze/freeze/pin resistance for %d turns.\
\9\9If the target is pinned and Charged Shield is sustained, its absorb value will be increased by %0.2f.\
\9\9If the target is frozen, the ice will melt in a flash of vapour, knocking back all creatures around it in radius 2.\
\9\9The discharge damage will scale with your Mindpower.", "tformat", true) -- 
tDef(324, "Psi Tap", "talent name", true) -- 
tDef(335, "Wrap a psionic energy field around your weapons, increasing their armour penentration by %d and allowing you to siphon excess energy from each weapon hit you land, gaining %0.1f psi per hit.", "tformat", true) -- 


