section "mod-tome/data/talents/psionic/dream-smith.lua"

tDef(61, "Dream Smith's Hammer", "talent name", true) -- 
tDef(111, "Craft a hammer from the dream forge and strike an adjacent foe, inflicting %d%% weapon damage. If the attack hits, it will bring one random Dream Smith talent off cooldown.\
\9\9At talent level 5, you'll bring a second random talent off cooldown.\
\9\9The base power, Accuracy, Armour penetration, and critical strike chance of the weapon will scale with your Mindpower.\
\9\9\
\9\9Current Dream Hammer Stats:\
\9\9%s", "tformat", true) -- 
tDef(121, "Hammer Toss", "talent name", true) -- 
tDef(163, "Hammer Toss", "_t", true) -- 
tDef(181, "Throw your Dream Hammer at a distant location, inflicting %d%% weapon damage on all targets between you and it.  After reaching its destination, the Dream Hammer will return, potentially hitting targets a second time.\
\9\9Learning this talent increases the Accuracy of your Dream Hammer by %d.", "tformat", true) -- 
tDef(187, "Dream Crusher", "talent name", true) -- 
tDef(213, "%s resists the stunning blow!", "logSeen", true) -- 
tDef(229, "Crush your enemy with your Dream Hammer, inflicting %d%% weapon damage.  If the attack hits, the target is stunned for %d turns.\
\9\9Stun chance improves with your Mindpower.  Learning this talent increases your Physical Power for Dream Hammer damage calculations by %d and all damage with Dream Hammer attacks by %d%%.\
\9\9", "tformat", true) -- 
tDef(236, "Forge Echoes", "talent name", true) -- 
tDef(284, "Strike an adjacent target with a mighty blow from the forge, inflicting %d%% weapon damage.  If the attack hits, the echo of the attack will lash out at all enemies in a %d radius of the impact.\
\9\9Learning this talent adds %0.2f mind damage and %0.2f burning damage to your Dream Hammer strikes.\
\9\9The mind and fire damage will scale with your Mindpower.", "tformat", true) -- 


