section "mod-tome/data/talents/psionic/focus.lua"

tDef(20, "Mindlash", "talent name", true) -- 
tDef(60, "Focus energies into a beam to lash all creatures in a line with physical force, doing %d Physical damage and knocking them off balance (-15%% damage penalty) for 2 turns.\
\9\9The damage will scale with your Mindpower.", "tformat", true) -- 
tDef(67, "Pyrokinesis", "talent name", true) -- 
tDef(98, "Telekinetically energize the matter of all foes within %d squares at the molecular level, setting them ablaze. This does %0.1f fire damage over six turns.", "tformat", true) -- 
tDef(104, "Brain Storm", "talent name", true) -- 
tDef(141, "Mentally focus electricity into a ball of plasma and hurl it at the target.\
\9\9The plasma will explode on impact, dealing %0.1f Lightning damage within radius %d.\
\9\9This talent will apply cross tier Brainlock.\
\9\9The damage will increase with your Mindpower.", "tformat", true) -- 
tDef(150, "Iron Will", "talent name", true) -- 
tDef(175, "#ORCHID#%s has recovered!", "logSeen", true) -- 
tDef(179, "Your Iron Will improves your stun immunity by %d%% and gives you a %d%% chance of recovering from a random mental effect each turn.", "tformat", true) -- 


