section "mod-tome/data/talents/psionic/kinetic-mastery.lua"

tDef(20, "Transcendent Telekinesis", "talent name", true) -- 
tDef(42, "For %d turns your telekinesis transcends your normal limits, increasing your Physical damage by %d%% and your Physical resistance penetration by %d%%.\
\9\9In addition:\
\9\9The cooldowns of Kinetic Shield, Kinetic Leech, Kinetic Aura, Kinetic Strike and Mindlash are reset.\
\9\9Kinetic Aura effects will have their radius increased by 1.\
\9\9Your Kinetic Shield will have 100%% absorption efficiency and will absorb twice the normal amount of damage.\
\9\9Mindlash will also inflict stun.\
\9\9Kinetic Leech will put enemies to sleep.\
\9\9Kinetic Strike will hit 2 adjacent enemies in a sweeping attack.\
\9\9The damage bonus and resistance penetration scale with your Mindpower.\
\9\9Only one Transcendent talent may be in effect at a time.", "tformat", true) -- 
tDef(56, "Kinetic Surge", "talent name", true) -- 
tDef(101, "%s resists the stun!", "logSeen", true) -- 
tDef(104, "#YELLOW##Source# resists #Target#'s throw!", "logCombat", true) -- 
tDef(143, "Build telekinetic power and dump it into an adjacent creature or yourself.\
\9\9This will launch them to a targeted location in radius %d.\
\
\9\9Launched enemies take %0.1f Physical damage and are stunned for %d turns upon landing.\
\9\9When the target lands, creatures within radius 2 take %0.1f Physical damage and are knocked away from you.\
\9\9This talent ignores %d%% of the knockback resistance of the thrown target, which takes half damage if it resists being thrown.\
\
\9\9When used on yourself, you will launch in a straight line, knocking enemies flying and doing %0.1f Physical damage to each.\
\9\9You can break through %d walls while doing this.\
\9\9The damage and range increases with Mindpower.", "tformat", true) -- 
tDef(159, "Deflect Projectiles", "talent name", true) -- 
tDef(210, "You learn to devote a portion of your attention to mentally swatting, grabbing, or otherwise deflecting incoming projectiles.\
\9\9All projectiles targeting you have a %d%% chance to instead target another spot within radius %d and move %d%% slower.\
\9\9If you choose, you can use your mind to grab all projectiles within radius 10 of you and hurl them toward any location within range %d of you, but this will break your concentration.\
\9\9To do this, deactivate this sustained talent.", "tformat", true) -- 
tDef(219, "Implode", "talent name", true) -- 
tDef(255, "Bind the target mercilessly with constant, bone-shattering pressure, pinning and slowing it by 50%% for %d turns and dealing %0.1f Physical damage each turn.\
\9\9The duration and damage improve with Mindpower.", "tformat", true) -- 


