section "mod-tome/data/talents/psionic/mentalism.lua"

tDef(23, "Psychometry", "talent name", true) -- 
tDef(69, "Resonate with psionic, nature, and anti-magic powered objects you wear, increasing your physical and mind power by %0.1f or %d%% of the object's material level (whichever is lower).\
\9\9This effect stacks and applies for each qualifying object worn.\
\9\9Current bonus: %d", "tformat", true) -- 
tDef(76, "Mental Shielding", "talent name", true) -- 
tDef(123, "%s's mind is clear!", "logSeen", true) -- 
tDef(129, "Clears your mind of current mental effects, and blocks additional ones over 6 turns.  At most, %d mental effects will be affected.", "tformat", true) -- 
tDef(134, "Projection", "talent name", true) -- 
tDef(148, "Not enough space to invoke your spirit!", "logPlayer", true) -- 
tDef(160, "Projection of %s", "tformat", true) -- 
tDef(161, "A ghostly figure.", "_t", true) -- 
tDef(225, "Activate to project your mind from your body for %d turns.  In this state you're invisible (+%d power), can see invisible and stealthed creatures (+%d detection power), can move through walls, and do not need air to survive.\
\9\9All damage you suffer is shared with your physical body, and while in this form you may only deal damage to 'ghosts' or through an active mind link (mind damage only in the second case.)\
\9\9To return to your body, simply release control of the projection.", "tformat", true) -- 
tDef(232, "Mind Link", "talent name", true) -- 
tDef(293, "Link minds with the target.  While your minds are linked, you'll inflict %d%% more mind damage to the target and gain telepathy for its creature type.\
\9\9Only one mindlink can be maintained at a time, and the effect will break if the target dies or goes beyond range (%d)).\
\9\9The mind damage bonus will scale with your Mindpower.", "tformat", true) -- 


