section "mod-tome/data/talents/psionic/psychic-assault.lua"

tDef(20, "Mind Sear", "talent name", true) -- 
tDef(54, "Sends a telepathic attack, trying to destroy the brains of any target in the beam, doing %0.2f mind damage.\
\9\9The damage will increase with your Mindpower.", "tformat", true) -- 
tDef(60, "Psychic Lobotomy", "talent name", true) -- 
tDef(94, "%s resists the lobotomy!", "logSeen", true) -- 
tDef(105, "Inflicts %0.2f mind damage and cripples the target's higher mental functions, reducing cunning by %d and confusing (%d%% power) the target for %d turns.\
\9\9The damage, cunning penalty, and confusion power will scale with your Mindpower.", "tformat", true) -- 
tDef(112, "Synaptic Static", "talent name", true) -- 
tDef(135, "Sends out a blast of telepathic static in a %d radius, inflicting %0.2f mind damage.  This attack can brainlock affected targets.\
\9\9The damage will increase with your Mindpower.", "tformat", true) -- 
tDef(141, "Sunder Mind", "talent name", true) -- 
tDef(176, "Cripples the target's mind, inflicting %0.2f mind damage and reducing its Mental Save by %d for 4 turns.  This attack always hits, and the mental save reduction stacks.\
\9\9Against brainlocked targets, the damage and Mental Save reduction will be doubled.\
\9\9The damage and save reduction will scale with your Mindpower.", "tformat", true) -- 


