section "mod-tome/data/talents/psionic/slumber.lua"

tDef(20, "Slumber", "talent name", true) -- 
tDef(66, "%s resists the sleep!", "logSeen", true) -- 
tDef(75, "Puts the target into a deep sleep for %d turns, rendering it unable to act.  Every %d points of damage the target suffers will reduce the effect duration by one turn.\
\9\9When Slumber ends, the target will suffer from Insomnia for a number of turns equal to the amount of time it was asleep (up to ten turns max), granting it %d%% sleep immunity for each turn of the Insomnia effect.\
\9\9The damage threshold will scale with your Mindpower.", "tformat", true) -- 
tDef(82, "Restless Night", "talent name", true) -- 
tDef(95, "Targets you have slept take %0.2f mind damage each turn for five turns upon waking.\
\9\9The damage will scale with your Mindpower.", "tformat", true) -- 
tDef(101, "Sandman", "talent name", true) -- 
tDef(111, "Increases the amount of damage you can deal to sleeping targets before reducing the effect duration by %d%%, and reduces the sleep immunity of your Insomnia effects by %d%%.\
\9\9These effects will be directly reflected in the appropriate talent descriptions.\
\9\9The damage threshold bonus will scale with your Mindpower.", "tformat", true) -- 
tDef(118, "Dreamscape", "talent name", true) -- 
tDef(133, "You feel it unwise to travel to the dreamscape in such a fragile form.", "logPlayer", true) -- 
tDef(136, "This talent cannot be used from within the Dreamscape.", "logPlayer", true) -- 
tDef(140, "This talent cannot be used here.", "logPlayer", true) -- 
tDef(156, "The spell fizzles...", "logPlayer", true) -- 
tDef(161, "Your target must be sleeping in order to enter its dreamscape.", "logPlayer", true) -- 
tDef(165, "You can't cast this on friendly targets.", "logPlayer", true) -- 
tDef(229, "#LIGHT_BLUE#You are taken to the Dreamscape!", "logPlayer", true) -- 
tDef(242, "Enter a sleeping target's dreams for %d turns.  While in the Dreamscape, you'll encounter the target's invulnerable sleeping form as well as dream projections that it will spawn every other turn to defend its mind.\
\9\9Projections inflict 50%% less damage than the original, unless the target has Lucid Dreamer active.\
\9\9When the Dreamscape ends, for each projection destroyed, the target's life will be reduced by 10%% and it will be brainlocked for one turn.\
\9\9In the Dreamscape, your damage will be improved by %d%%.\
\9\9The damage bonus will improve with your Mindpower.", "tformat", true) -- 


------------------------------------------------
section "mod-tome/data/talents/psionic/solipsism.lua"

tDef(20, "Solipsism", "talent name", true) -- 
tDef(58, "You believe that your mind is the center of everything.  Permanently increases the amount of psi you gain per level by 5 and reduces your life rating (affects life at level up) by 50%% (one time only adjustment).\
\9\9You also have learned to overcome damage with your mind alone, and convert %d%% of all damage you receive into Psi damage and %d%% of your healing and life regen now recovers Psi instead of life.\
\9\9Converted Psi damage you take will be further reduced by %0.1f%% (%0.1f%% from character level with the remainder further reduced by %0.1f%% from talent level).\
\9\9The first talent point invested will also increase the amount of Psi you gain from Willpower by 0.5, but reduce the amount of life you gain from Constitution by 0.25.\
\9\9The first talent point also increases your solipsism threshold by 20%% (currently %d%%), reducing your global speed by 1%% for each percentage your current Psi falls below this threshold.", "tformat", true) -- 
tDef(67, "Balance", "talent name", true) -- 
tDef(98, "You now substitute %d%% of your Mental Save for %d%% of your Physical and Spell Saves throws (so at 100%%, you would effectively use mental save for all saving throw rolls).\
\9\9The first talent point invested will also increase the amount of Psi you gain from Willpower by 0.5, but reduce the amount of life you gain from Constitution by 0.25.\
\9\9Learning this talent also increases your solipsism threshold by 10%% (currently %d%%).", "tformat", true) -- 
tDef(105, "Clarity", "talent name", true) -- 
tDef(141, "For every percent that your Psi pool exceeds %d%%, you gain 1%% global speed (up to a maximum of %+d%%).\
\9\9The first talent point invested will also increase the amount of Psi you gain from Willpower by 0.5, but reduce the amount of life you gain from Constitution by 0.25 and will increase your solipsism threshold by 10%% (currently %d%%).", "tformat", true) -- 
tDef(148, "Dismissal", "talent name", true) -- 
tDef(183, "#TAN##Source# mentally dismisses some damage!", "delayedLogMessage", true) -- 
tDef(184, "#TAN#(%d dismissed)#LAST#", "tformat", true) -- 
tDef(192, "Each time you take damage, you roll %d%% of your mental save against it.  A successful saving throw can crit and will reduce the damage by at least 50%%.\
\9\9The first talent point invested will also increase the amount of Psi you gain from Willpower by 0.5, but reduce the amount of life you gain from Constitution by 0.25.\
\9\9The first talent point also increases your solipsism threshold by 10%% (currently %d%%).", "tformat", true) -- 


