section "mod-tome/data/talents/psionic/thought-forms.lua"

tDef(140, "thought-form", "_t", true) -- 
tDef(165, "Thought-Form: Bowman", "talent name", true) -- 
tDef(186, "Not enough space to summon!", "logPlayer", true) -- 
tDef(195, "thought-forged bowman", "_t", true) -- 
tDef(198, "A thought-forged bowman.  It appears ready for battle.", "_t", true) -- 
tDef(260, "Forge a bowman, clad in leather armor, from your thoughts.  The bowman learns Bow Mastery, Combat Accuracy, Steady Shot, Crippling Shot, and Rapid Shot as it levels up, and has +%d Strength, +%d Dexterity, and +%d Constitution.\
\9\9Activating this talent will put all other thought-forms on cooldown.\
\9\9The stat bonuses will improve with your Mindpower.", "tformat", true) -- 
tDef(267, "Thought-Form: Warrior", "talent name", true) -- 
tDef(297, "thought-forged warrior", "_t", true) -- 
tDef(300, "A thought-forged warrior wielding a massive battle-axe and clad in heavy armor.  It appears ready for battle.", "_t", true) -- 
tDef(362, "Forge a warrior wielding a battle-axe from your thoughts.  The warrior learns Weapon Mastery, Combat Accuracy, Berserker, Death Dance, and Rush as it levels up, and has +%d Strength, +%d Dexterity, and +%d Constitution.\
\9\9Activating this talent will put all other thought-forms on cooldown.\
\9\9The stat bonuses will improve with your Mindpower.", "tformat", true) -- 
tDef(369, "Thought-Form: Defender", "talent name", true) -- 
tDef(399, "thought-forged defender", "_t", true) -- 
tDef(402, "A thought-forged defender clad in massive armor.  It wields a sword and shield and appears ready for battle.", "_t", true) -- 
tDef(466, "Forge a defender wielding a sword and shield from your thoughts.  The solider learns Armor Training, Weapon Mastery, Combat Accuracy, Shield Pummel, and Shield Wall as it levels up, and has +%d Strength, +%d Dexterity, and +%d Constitution.\
\9\9Activating this talent will put all other thought-forms on cooldown.\
\9\9The stat bonuses will improve with your Mindpower.", "tformat", true) -- 
tDef(473, "Thought-Forms", "talent name", true) -- 
tDef(507, "Forge a guardian from your thoughts alone.  Your guardian's primary stat will be improved by %d, its two secondary stats by %d, and it will have Magic, Cunning, and Willpower equal to your own.\
\9\9At talent level one, you may forge a mighty bowman clad in leather armor; at level three a powerful warrior wielding a two-handed weapon; and at level five a strong defender using a sword and shield.\
\9\9Thought forms can only be maintained up to a range of %d, and will rematerialize next to you if this range is exceeded.\
\9\9Only one thought-form may be active at a time, and the stat bonuses will improve with your Mindpower.", "tformat", true) -- 
tDef(515, "Transcendent Thought-Forms", "talent name", true) -- 
tDef(523, "Your thought-forms now know Lucid Dreamer, Biofeedback, and Psychometry at talent level %d.", "tformat", true) -- 
tDef(528, "Over Mind", "talent name", true) -- 
tDef(540, "You must have an active Thought-Form to use this talent!", "logPlayer", true) -- 
tDef(600, "Take direct control of your active thought-form, improving its damage, attack speed, and maximum life by %d%%, but leaving your body a defenseless shell.\
\9\9At talent level 1, any Feedback your Thought-Forms gain will be given to you as well. At level 3, your Thought-Forms gain a bonus to all saves equal to your Mental Save. At level 5, they gain a bonus to all damage equal to your bonus mind damage.\
\9\9The secondary bonuses apply whether or not this talent is currently active.\
\9\9The life, damage, and speed bonus will improve with your Mindpower.", "tformat", true) -- 
tDef(608, "Thought-Form Unity", "talent name", true) -- 
tDef(621, "You now gain %d%% mind speed while Thought-Form: Bowman is active, %d Mindpower while Thought-Form: Warrior is active, and %d%% resist all while Thought-Form: Defender is active. \
\9\9These bonuses scale with your Mindpower.", "tformat", true) -- 


