section "mod-tome/data/talents/psionic/voracity.lua"

tDef(21, "Kinetic Leech", "talent name", true) -- 
tDef(67, "%s resists the sleep!", "logSeen", true) -- 
tDef(78, "You draw kinetic energy from your surroundings to replenish your Psi.\
\9\9This will slow all targets within radius %d by %d%% (max %d%%) for four turns, draining %0.1f (max %0.1f) stamina from each.\
\9\9You replenish %d (max %d) Psi from the first target, with each additional target restoring 20%% less than the one before it.\
\9\9The strength of these effects increases as your Psi depletes and with your Mindpower.", "tformat", true) -- 
tDef(87, "Thermal Leech", "talent name", true) -- 
tDef(138, "You draw thermal energy from your surroundings to replenish your Psi.\
\9\9This will freeze all targets within radius %d for %d (max %d) turns, and deal %0.1f (max %0.1f) Cold damage.\
\9\9You replenish %d (max %d) Psi from the first target, with each additional target restoring 20%% less than the one before it.\
\9\9The damage and the strength of these effects increases as your Psi depletes and with your Mindpower.", "tformat", true) -- 
tDef(147, "Charge Leech", "talent name", true) -- 
tDef(207, "You draw electical potential energy from your surroundings to replenish your Psi.\
\9\9This deals %0.1f (max %0.1f) Lightning damage to all targets around you within radius %d, and has a %d%% (max %d%%) chance to daze them for 3 turns.\
\9\9You replenish %d (max %d) Psi from the first target, with each additional target restoring 20%% less than the one before it.\
\9\9The strength of these effects increases as your Psi depletes and with your Mindpower.", "tformat", true) -- 
tDef(216, "Insatiable", "talent name", true) -- 
tDef(230, "Increases your maximum energy by %d. You also gain %0.1f Psi for each kill and %0.1f Psi for each mind critical.", "tformat", true) -- 


