section "mod-tome/data/talents/spells/advanced-golemancy.lua"

tDef(22, "Life Tap", "talent name", true) -- 
tDef(25, "Having an Alchemist Golem", "_t", true) -- 
tDef(39, "Your golem is currently inactive.", "logPlayer", true) -- 
tDef(58, "You tap into your golem's life energies to replenish your own. Drains %d life.", "tformat", true) -- 
tDef(64, "Gem Golem", "talent name", true) -- 
tDef(71, "Insert a pair of gems into your golem, providing it with the gem bonuses and changing its melee attack damage type. You may remove the gems and insert different ones; this does not destroy the gems you remove.\
\9\9Gem level usable: %d\
\9\9Gem changing is done in the golem's inventory.", "tformat", true) -- 
tDef(78, "Supercharge Golem", "talent name", true) -- 
tDef(98, "Not enough space to supercharge!", "logPlayer", true) -- 
tDef(123, "You activate a special mode of your golem, boosting its regeneration rate by %0.2f life per turn for %d turns.\
\9\9If your golem was dead, it is instantly brought back to life with %d%% life.\
\9\9While supercharged, your golem is enraged and deals 25%% more damage.", "tformat", true) -- 
tDef(133, "Runic Golem", "talent name", true) -- 
tDef(163, "Increases your golem's life, mana and stamina regeneration rates by %0.2f.\
\9\9At level 1, 3 and 5, the golem also gains a new rune slot.\
\9\9Even without this talent, Golems start with three rune slots.", "tformat", true) -- 


