section "mod-tome/data/talents/spells/air.lua"

tDef(20, "Lightning", "talent name", true) -- 
tDef(57, "Conjures up mana into a powerful beam of lightning, doing %0.2f to %0.2f damage (%0.2f average)\
\9\9The damage will increase with your Spellpower.", "tformat", true) -- 
tDef(67, "Chain Lightning", "talent name", true) -- 
tDef(140, "Invokes an arc of lightning doing %0.2f to %0.2f damage (%0.2f average) and chaining to another target.\
\9\9The arc can jump to %d targets at most, up to 10 grids apart, and will never jump to the same target twice, or to the caster. The arc will also strike all creatures between each target.\
\9\9The damage will increase with your Spellpower.", "tformat", true) -- 
tDef(151, "Feather Wind", "talent name", true) -- 
tDef(195, "A gentle wind circles around the caster, increasing carrying capacity by %d, defense against projectiles by %d, pin immunity by %d%% and stun immunity by %d%%.\
\9\9At level 4 it also makes you levitate slightly above the ground, allowing you to ignore some traps.\
\9\9At level 5 it also grants %d%% movement speed and removes %d fatigue.", "tformat", true) -- 
tDef(203, "Thunderstorm", "talent name", true) -- 
tDef(240, "#0080FF#A furious lightning storm forms around %s!", "logSeen", true) -- 
tDef(246, "#0080FF#The furious lightning storm around %s calms down and disappears.", "logSeen", true) -- 
tDef(252, "Conjures a furious, raging lightning storm with a radius of 6 that follows you as long as this spell is active.\
\9\9Each turn, a random lightning bolt will hit up to %d of your foes for 1.00 to %0.2f damage (%0.2f average) in a radius of 1.\
\9\9The damage will increase with your Spellpower.", "tformat", true) -- 


