section "mod-tome/data/talents/spells/animus.lua"

tDef(20, "Soul Leech", "talent name", true) -- 
tDef(68, "Each time you or your undead minions deal damage to a creature you apply Soul Leech to them.\
\9\9If a creature dies with this effect active, you steal its soul.\
\9\9Strong creatures and bosses are so overflowing with soul power that you steal a fragment of their soul every few turns:\
\9\9%s- rare: at most every %d turns\
\9\9%s- unique: at most every %d turns\
\9\9%s- boss: at most every %d turns\
\9\9%s- elite boss: at most every %d turns#WHITE#\
\
\9\9Also increases your maximum souls capacity by %d .\
\9\9", "tformat", true) -- 
tDef(82, "Consume Soul", "talent name", true) -- 
tDef(103, "Consume a soul whole to rebuild your body, healing you for %d and generating %d mana.\
\9\9If used below 1 life the surge increases your spellpower by %d for 10 turns.\
\9\9The heal and mana increases with your Spellpower.", "tformat", true) -- 
tDef(111, "Torture Souls", "talent name", true) -- 
tDef(138, "Unleash dark forces to all foes in sight that are afflicted by Soul Leech, dealing %0.2f frostdusk damage to them and tearing apart their souls.\
\9\9This returns up to %d souls to you (one for each foe hit).\
\9\9The damage increases with your Spellpower.", "tformat", true) -- 
tDef(146, "Reaping", "talent name", true) -- 
tDef(184, "You draw constant power from the souls you hold within your grasp.\
\9\9If you hold at least 2, your mana regeneration is increased by %0.1f per turn.\
\9\9If you hold at least 5, your spellpower is increased by %d.\
\9\9If you hold at least 8, all your resistances are increased by %d.", "tformat", true) -- 


