section "mod-tome/data/talents/spells/arcane.lua"

tDef(21, "Manathrust", "talent name", true) -- 
tDef(64, "Conjures up mana into a powerful bolt doing %0.2f arcane damage.\
\9\9At level 3, it becomes a beam.\
\9\9The damage will increase with your Spellpower.", "tformat", true) -- 
tDef(72, "Arcane Power", "talent name", true) -- 
tDef(100, "Your mastery of magic allows you to enter a state of deep concentration, increasing your Spellpower by %d and arcane resistance by %d%%.", "tformat", true) -- 
tDef(106, "Arcane Vortex", "talent name", true) -- 
tDef(134, "Creates a vortex of arcane energies on the target for 6 turns. Each turn the vortex will look for another foe in sight and fire a manathrust doing %0.2f arcane damage to all foes in line.\
\9\9If no foes are found, the target will take 50%% more arcane damage.\
\9\9If the target dies, the vortex explodes, releasing all remaining damage in a radius 2 ball of arcane force.\
\9\9The damage will increase with your Spellpower.", "tformat", true) -- 
tDef(144, "Disruption Shield", "talent name", true) -- 
tDef(168, "#VIOLET#%s's disruption shield collapses and then explodes in a powerful manastorm!", "logSeen", true) -- 
tDef(239, "#SLATE#(%d absorbed)#LAST#", "tformat", true) -- 
tDef(278, "#PURPLE#(%d mana)#LAST#", "tformat", true) -- 
tDef(294, "%s restores Disruption Shield (+%d) and gains %d mana with Aegis!", "logSeen", true) -- 
tDef(297, "%s restores Disruption Shield (+%d) with Aegis!", "logSeen", true) -- 
tDef(336, "Surround yourself with arcane forces, disrupting any attempts to harm you by creating a shield of pure aether which can absorb %d damage.\
\9\9In combat, the mental focus required to maintain and monitor the shield is too much and you let it run on its own. In this state once the shield power is depleted it will start using your mana to absorb hits, at a ratio of %0.2f mana per damage.\
\9\9Whenever mana is used by the shield it stores a remnant of this energy (up to %d max). When the shield is deactivated any stored energy is released in a radius %d arcane storm that lasts 5 turns, dealing 20%% of the total stored damage each turn.\
\9\9Outside of combat the shield regenerates 10%% of its power each turn and stored energy quickly dissipates.\
\9\9Dropping below 50%% mana or reaching max energy storage will automatically deactivate this talent.\
\9\9The shield power improves with your Spellpower.\
\9\9The maximum energy storage is based on your total mana (ignoring sustained spells), with a limit at %d effective mana.\
\
\9\9Current shield power: %d\
\9\9Current stored energy: %d", "tformat", true) -- 


