section "mod-tome/data/talents/spells/conveyance.lua"

tDef(66, "Phase Door", "talent name", true) -- 
tDef(83, "Select a target to teleport...", "logPlayer", true) -- 
tDef(99, "The spell fizzles!", "logSeen", true) -- 
tDef(109, "Select a teleport location...", "logPlayer", true) -- 
tDef(140, "The targeted phase door fizzles and works randomly!", "logPlayer", true) -- 
tDef(162, "Teleports you randomly within a small range of up to %d grids.\
\9\9At level 4, it allows you to specify which creature to teleport.\
\9\9At level 5, it allows you to choose the target area (radius %d).\
\9\9If the target area is not in line of sight, there is a chance the spell will partially fail and teleport the target randomly.\
\9\9The range will increase with your Spellpower.", "tformat", true) -- 
tDef(171, "Teleport", "talent name", true) -- 
tDef(248, "The targetted teleport fizzles and works randomly!", "logPlayer", true) -- 
tDef(277, "Teleports you randomly within a large range (%d).\
\9\9At level 4, it allows you to specify which creature to teleport.\
\9\9At level 5, it allows you to choose the target area (radius %d).\
\9\9If the target area is not in line of sight, there is a chance the spell will partially fail and teleport the target randomly.\
\9\9Random teleports have a minimum range of %d.\
\9\9The range will increase with your Spellpower.", "tformat", true) -- 
tDef(287, "Displacement Shield", "talent name", true) -- 
tDef(316, "This intricate spell erects a space distortion around the caster that is linked to another distortion, placed around a target.\
\9\9Any time the caster should take damage, there is a %d%% chance that it will instead be warped by the shield and hit the designated target.\
\9\9Once the maximum damage (%d) is absorbed, the time runs out (%d turns), or the target dies, the shield will crumble.\
\9\9The max damage the shield can absorb will increase with your Spellpower.", "tformat", true) -- 
tDef(325, "Probability Travel", "talent name", true) -- 
tDef(349, "When you hit a solid surface, this spell tears down the laws of probability to make you instantly appear on the other side.\
\9\9Teleports up to %d grids.\
\9\9After a successful probability travel you are left unstable, unable to do it again for a number of turns equal to %d%% of the number of tiles you blinked through.\
\9\9The range will improve with your Spellpower.", "tformat", true) -- 


