section "mod-tome/data/talents/spells/death.lua"

tDef(20, "Rigor Mortis", "talent name", true) -- 
tDef(56, "%s resists the Rigor Mortis!", "logSeen", true) -- 
tDef(65, "Press your advantage when your foes are starting to crumble.\
\9\9For every detrimental effect on the target you deals %0.2f frostdusk damage (with diminishing returns) and reduce its global speed by 25%% for one turn per effect (up to a maximum of %d).\
\9\9The diminishing returns on damage bonus works this way:\
\9\9- 2 effects: %0.2f\
\9\9- 5 effects: %0.2f\
\9\9- 10 effects: %0.2f\
\9\9- 15 effects: %0.2f\
\9\9And so on...\
\9\9Damage increases with your Spellpower.\
\9\9", "tformat", true) -- 
tDef(79, "Drawn To Death", "talent name", true) -- 
tDef(154, "Every time you or one of your minions kill a creature you create a temporary link to the place of death.\
\9\9For %d turns afterwards you can instantly and accurately teleport to it (if it is in sight).\
\9\9", "tformat", true) -- 
tDef(161, "Grim Shadow", "talent name", true) -- 
tDef(181, "#GREY#Darkness pulsates around %s!", "logSeen", true) -- 
tDef(203, "Your body starts to radiate shadows, increasing your darkness resistance by %d%%, armour by %d and defence by %d.\
\9\9Any time you absorb a soul the shadows pulse outward, dealing %0.2f frostdusk damage to all foes in range %d and knocking them back 3 tiles.\
\9\9This can only happen once per turn.\
\9\9The damage increases with your Spellpower.", "tformat", true) -- 
tDef(212, "Utterly Destroyed", "talent name", true) -- 
tDef(240, "Whenever a creature is killed by yourself or a minion you feast on its essence, gaining %0.1f mana.\
\9\9At level 3 the thrill of the death invigorates you, granting a movement speed bonus of 50%% for %d turns.", "tformat", true) -- 


