section "mod-tome/data/talents/spells/dreadmaster.lua"

tDef(20, "Dread", "talent name", true) -- 
tDef(157, "Summon a Dread of level %d that will annoyingly blink around, hexing your foes.\
\9\9It knows the following spells:\
\9\9- Burning Hex at level %d\
\9\9- Empathic Hex at level %d\
\9\9- Pacification Hex at level %d\
\9\9- Blur Sight at level %d\
\9\9- Phase Door at level %d\
\9\9", "tformat", true) -- 
tDef(169, "Souleater", "talent name", true) -- 
tDef(188, "#GREY#%s has fed on enough minions and starts to randomly hex foes!", "logSeen", true) -- 
tDef(210, "Any time one of your minions dies or expires, and even if it is resurrected by a boneyard, the dread feeds on it.\
\9\9Each time it feeds it gets healed for %d and reduces remaining cooldown of its spells by %d.\
\9\9Every 10 minion deaths it casts a random hex on up to %d foes at once, instantly and without triggering a cooldown.", "tformat", true) -- 
tDef(218, "Neverending Peril", "talent name", true) -- 
tDef(235, "In an effort to make your dread more annoying you focus a shell of darkness around it, rendering it fully invincible for %d turns.", "tformat", true) -- 
tDef(241, "Dreadmaster", "talent name", true) -- 
tDef(256, "You now summon a Dreadmaster instead of a Dread.\
\9\9Dreadmasters learn to cast silence, disperse magic and mind disruption, making them the ultimate annoyance tool.\
\9\9It learns them at talent level %d.", "tformat", true) -- 


