section "mod-tome/data/talents/spells/master-necromancer.lua"

tDef(20, "Aura of Undeath", "talent name", true) -- 
tDef(49, "Your mastery of necromancy becomes so total that an aura of undeath radiates around you in radius %d.\
\9\9Any undead minion standing inside of it is protected, increasing all their resistances by %d%%.\
\9\9In addition when you create new minions they inherit %d%% of your spellpower (applied to any powers), spell crit chance (applied to any crit chances), saves, resists, and highest damage increase (applied to all elements).\
\9\9", "tformat", true) -- 
tDef(57, "Surge of Undeath", "talent name", true) -- 
tDef(98, "Sends out a surge of undeath energies into your aura.\
\9\9All minions inside gain 25%% speed for %d turns\
\9\9All non-ghoul minions are healed by %d%%.\
\9\9If you know Call of the Mausoleum, the time remaining to the next free ghoul is reduced by %d.\
\9\9if you know Corpse Explosion or Putrescent Liquefaction the duration of those effects are increased by %d.\
\9\9All non-undead foes caught inside are dazed for %d turns.\
\9\9In addition all your minions (created after you learn this spell) have a passive health regeneration.", "tformat", true) -- 
tDef(110, "Recall Minions", "talent name", true) -- 
tDef(154, "Tighten the ethereal leash to some of your minions currently within your aura of undeath, pulling them to you and swapping place with any eventual foes in the way.\
\9\9Up to %d minions are affected.\
\9\9When recalling a minion the spell tries to prioritize a spot where there is already a foe, to push it away.", "tformat", true) -- 
tDef(162, "Suffer For Me", "talent name", true) -- 
tDef(183, "#GREY#(%d to minion: %s)#LAST#", "tformat", true) -- 
tDef(196, "By creating an arcane link with your minion army you are able to redirect parts of any damage affecting you to them.\
\9\9Anytime you take damage %d%% of it is instead redirected to a random minion within your aura of undeath.\
\9\9The minion takes 300%% damage from that effect.\
\9\9The damage redirected percent depends on your Spellpower.", "tformat", true) -- 


