tDef(148, "Tempest", "talent name", true) -- 
tDef(185, "Surround yourself with a Tempest, increasing all your lightning damage by %d%% and ignoring %d%% lightning resistance of your targets.\
\9\9Your Lightning and Chain Lightning spells also gain a %d%% chance to daze, and your Thunderstorm spell gains a %d%% chance to daze.", "tformat", true) -- 


