section "mod-tome/data/talents/spells/temporal.lua"

tDef(20, "Congeal Time", "talent name", true) -- 
tDef(49, "Project a bolt of time distortion, decreasing the target's global speed by %d%% and all projectiles it fires by %d%% for 7 turns.", "tformat", true) -- 
tDef(55, "Temporal Shield", "talent name", true) -- 
tDef(78, "This intricate spell instantly erects a time shield around the caster, preventing any incoming damage and sending it forward in time.\
\9\9Once either the maximum damage (%d) is absorbed, or the time runs out (%d turns), the stored damage will return as a temporal restoration field over time (5 turns).\
\9\9Each turn the restoration field is active, you get healed for 10%% of the absorbed damage (Aegis Shielding talent affects the percentage).\
\9\9The shield's max absorption will increase with your Spellpower.", "tformat", true) -- 
tDef(87, "Time Prison", "talent name", true) -- 
tDef(111, "Removes the target from the flow of time for %d turns. In this state, the target can neither act nor be harmed.\
\9\9Time does not pass at all for the target, no talents will cooldown, no resources will regen, and so forth.\
\9\9The duration will increase with your Spellpower.", "tformat", true) -- 
tDef(119, "Essence of Speed", "talent name", true) -- 
tDef(142, "Increases the caster's global speed by %d%%.", "tformat", true) -- 


