section "mod-tome/data/talents/techniques/bloodthirst.lua"

tDef(20, "Mortal Terror", "talent name", true) -- 
tDef(39, "%s resists the terror!", "logSeen", true) -- 
tDef(46, "Your mighty blows inspire utter terror on your foes. Any melee strike you do that deals more than %d%% of the target's total life puts them in a mortal terror, dazing them for 5 turns.\
\9\9Your critical strike chance also increase by %d%%.\
\9\9The daze chance increase with your Physical Power.", "tformat", true) -- 
tDef(54, "Bloodbath", "talent name", true) -- 
tDef(71, "Delight in spilling the blood of your foes.  After scoring a critical hit, your maximum hit points will be increased by %d%%, your life regeneration by %0.2f per turn, and your stamina regeneration by %0.2f per turn for %d turns.\
\9\9The life and stamina regeneration will stack up to five times, for a maximum of %0.2f and %0.2f each turn, respectively.", "tformat", true) -- 
tDef(78, "Bloody Butcher", "talent name", true) -- 
tDef(86, "You delight in the inflicting of wounds, providing %d physical power.\
\9\9In addition when you make a creature bleed its physical damage resistance is reduced by %d%% (but never below 0%%).\
\9\9Physical power depends on your Strength stat.", "tformat", true) -- 
tDef(94, "Unstoppable", "talent name", true) -- 
tDef(121, "You enter a battle frenzy for %d turns. During that time, you can not use items, healing has no effect, and your health cannot drop below 1.\
\9\9At the end of the frenzy, you regain %d%% of your health per foe slain during the frenzy.\
\9\9While Unstoppable is active, Berserker Rage critical bonus is disabled as you lose the thrill of the risk of death.", "tformat", true) -- 


