section "mod-tome/data/talents/techniques/conditioning.lua"

tDef(20, "Vitality", "talent name", true) -- 
tDef(42, "You recover faster from poisons, diseases and wounds, reducing the duration of all such effects by %d%%.  \
\9\9\9Whenever your life falls below 50%%, your life regeneration increases by %0.1f for %d turns (%d total). This effect can only happen once every %d turns.\
\9\9The regeneration scales with your Constitution.", "tformat", true) -- 
tDef(50, "Unflinching Resolve", "talent name", true) -- 
tDef(84, "#ORCHID#%s has recovered!#LAST#", "logSeen", true) -- 
tDef(90, "You've learned to recover quickly from effects that would disable you. Each turn, you have a %d%% chance to recover from a single stun effect.\
\9\9At talent level 2 you may also recover from Blindness, at level 3 Confusion and Pins, and level 4 Disarms and Slows.\
\9\9Effects will be cleansed with the priority order Stun > Blind > Confusion > Pin > Disarm > Slow.\
\9\9Only one effect may be recovered from each turn, and the chance to recover from an effect scales with your Constitution.", "tformat", true) -- 
tDef(99, "Daunting Presence", "talent name", true) -- 
tDef(135, "Enemies are intimidated by your very presence.\
\9\9Enemies within radius %d have their Physical Power, Mindpower, and Spellpower reduced by %d.\
\9\9The power of the intimidation effect improves with your Physical power", "tformat", true) -- 
tDef(143, "Adrenaline Surge", "talent name", true) -- 
tDef(163, "You release a surge of adrenaline that increases your Physical Power by %d for %d turns. While the effect is active, you may continue to fight beyond the point of exhaustion.\
\9\9You may continue to use stamina based talents while at zero stamina at the cost of life.\
\9\9The Physical Power increase will scale with your Constitution.\
\9\9Using this talent does not take a turn.", "tformat", true) -- 


