section "mod-tome/data/talents/techniques/dualweapon.lua"

tDef(23, "Dual Weapon Training", "talent name", true) -- 
tDef(34, "Increases the damage of your off-hand weapon to %d%%.", "tformat", true) -- 
tDef(39, "Dual Weapon Defense", "talent name", true) -- 
tDef(83, "You have learned to block incoming blows with your offhand weapon.\
\9\9When dual wielding, your defense is increased by %d.\
\9\9Up to %0.1f times a turn, you have a %d%% chance to parry up to %d damage (based on your your offhand weapon damage) from a melee attack.\
\9\9A successful parry reduces damage like armour (before any attack multipliers) and prevents critical strikes.  Partial parries have a proportionally reduced chance to succeed.  It is difficult to parry attacks from unseen attackers and you cannot parry with a mindstar.\
\9\9The defense and chance to parry improve with Dexterity.  The number of parries increases with Cunning.", "tformat", true) -- 
tDef(93, "Close Combat Management", "talent name", true) -- 
tDef(107, "You must dual wield to use this talent.", "logPlayer", true) -- 
tDef(136, "You must dual wield to manage contact with your target!", "logPlayer", true) -- 
tDef(146, "You have learned how to carefully manage contact between you and your opponent.\
\9\9When striking in melee with your dual wielded weapons, you automatically avoid up to %d damage dealt to you from each of your target's on hit effects.  This improves with your Dexterity, but is not possible with mindstars.\
\9\9In addition, while this talent is active, you redirect %d%% of the damage you avoid this way back to your target.", "tformat", true) -- 
tDef(155, "Offhand Jab", "talent name", true) -- 
tDef(165, "You require two weapons to use this talent.", "logPlayer", true) -- 
tDef(178, "You must dual wield to perform an Offhand Jab!", "logPlayer", true) -- 
tDef(197, "%s resists the surprise strike!", "logSeen", true) -- 
tDef(204, "With a quick shift of your momentum, you execute a surprise unarmed strike in place of your normal offhand attack.\
\9\9This allows you to attack with your mainhand weapon for %d%% damage and unarmed for %d%% damage.  If the unarmed attack hits, the target is confused (%d%% power) for %d turns.\
\9\9The chance to confuse increases with your Accuracy.", "tformat", true) -- 
tDef(215, "Dual Strike", "talent name", true) -- 
tDef(230, "You cannot use Dual Strike without dual wielding!", "logPlayer", true) -- 
tDef(247, "%s resists the stunning strike!", "logSeen", true) -- 
tDef(257, "Attack with your offhand weapon for %d%% damage. If the attack hits, the target is stunned for %d turns, and you hit it with your mainhand weapon doing %d%% damage.\
\9\9The stun chance increases with your Accuracy.", "tformat", true) -- 
tDef(264, "Flurry", "talent name", true) -- 
tDef(278, "You cannot use Flurry without dual wielding!", "logPlayer", true) -- 
tDef(293, "Lashes out with a flurry of blows, hitting your target three times with each weapon for %d%% damage.", "tformat", true) -- 
tDef(298, "Heartseeker", "talent name", true) -- 
tDef(360, "Swiftly leap to your target and strike at their vital points with both weapons, dealing %d%% weapon damage. This attack deals %d%% increased critical strike damage.", "tformat", true) -- 
tDef(366, "Whirlwind", "talent name", true) -- 
tDef(400, "The target location must be within range and within view.", "logPlayer", true) -- 
tDef(419, "There is no open space in which to land near there.", "logPlayer", true) -- 
tDef(423, "%s becomes a whirlwind of weapons!", "logSeen", true) -- 
tDef(452, "You quickly move up to %d tiles to arrive adjacent to a target location you can see, leaping around or over anyone in your way.  During your movement, you attack all foes within one grid of your path with both weapons for %d%% weapon damage, causing those struck to bleed for 50%% of the damage dealt over 5 turns.", "tformat", true) -- 


