section "mod-tome/data/talents/techniques/grappling.lua"

tDef(21, "Grappling Stance", "talent name", true) -- 
tDef(49, "Increases your Physical Save by %d and your Physical Power by %d.\
\9\9The bonuses will scale with your Strength.", "tformat", true) -- 
tDef(56, "Clinch", "talent name", true) -- 
tDef(103, "Make a melee attack for %d%% damage and then attempt to grapple a target up to one size category larger than yourself for %d turns. A grappled opponent will be unable to move, take %d damage each turn, and %d%% of the damage you receive from any source will be redirected to them as physical damage.\
\9\9Any movement from the target or you will break the grapple. Maintaining a grapple drains %d stamina per turn.\
\9\9You may only grapple a single target at a time, and using any targeted unarmed talent on a target that you're not grappling will break the grapple.", "tformat", true) -- 
tDef(111, "Crushing Hold", "talent name", true) -- 
tDef(143, "Enhances your grapples with additional effects. All additional effects will apply to every grapple with no additional save or resist check.\
\9\9#RED#Talent Level 1:  Reduces physical power by %d\
\9\9Talent Level 3:  Silences\
\9\9Talent Level 5:  Reduces global action speed by %d%%", "tformat", true) -- 
tDef(152, "Take Down", "talent name", true) -- 
tDef(193, "You cannot move!", "logPlayer", true) -- 
tDef(241, "Rushes forward and attempts to take the target to the ground, making a melee attack for %d%% damage then attempting to grapple them. If you're already grappling the target you'll instead slam them into the ground creating a radius 5 shockwave for %d physical damage and breaking your grapple.\
\9\9The grapple effects and duration will be based off your grapple talent, if you have it, and the damage will scale with your Physical Power.", "tformat", true) -- 
tDef(248, "Hurricane Throw", "talent name", true) -- 
tDef(275, "You must be grappling something to use this talent.", "logPlayer", true) -- 
tDef(279, "Your grapple victim must be able to move to use this talent.", "logPlayer", true) -- 
tDef(325, "#RED#%s is shaken by the collision and loses a turn!#LAST#", "logSeen", true) -- 
tDef(336, "In a mighty show of strength you whirl your grappled victim around and throw them into the air causing %d%% damage to them and enemies in radius %d on landing.  \
\9\9\9If at least 1 other enemy is hit the thrown enemy will be shaken by the impact losing a full turn.\
\9\9\9You can only throw enemies that could move normally.", "tformat", true) -- 


