section "mod-tome/data/talents/techniques/magical-combat.lua"

tDef(20, "Arcane Combat", "talent name", true) -- 
tDef(162, "\9\9\9\9\
\9\9\9\9Currently selected spell: %s", "tformat", true) -- 
tDef(166, "\9\9\9\9\
\9\9\9\9Currently selected spell: Random", "_t", true) -- 
tDef(171, "Allows you to use melee weapons to focus your spells, granting a %d%% chance per melee attack to cast an offensive spell as a free action on the target.\
\9\9Delivering the spell this way will not trigger a spell cooldown.\
\9\9You may select an allowed spell to trigger this way, or choose to have one randomly selected for each attack.\
\9\9While dual wielding or using a shield the chance is halved.\
\9\9The chance increases with your Cunning.\
\
\9\9Allowed spells: %s %s", "tformat", true) -- 
tDef(183, "Arcane Cunning", "talent name", true) -- 
tDef(193, "The user gains a bonus to Spellpower equal to %d%% of your Cunning (Current bonus: %d).", "tformat", true) -- 
tDef(199, "Arcane Feed", "talent name", true) -- 
tDef(226, "Regenerates %0.2f mana per turn, and increases physical and spell critical chance by %d%% while active.", "tformat", true) -- 
tDef(231, "Arcane Destruction", "talent name", true) -- 
tDef(240, "Raw magical damage channels through the caster's weapon, increasing raw Physical Power by %d%% of your Magic (current bonus: %d).\
\9\9Each time you crit with a melee blow, you will unleash a radius %d ball of arcane damage, doing %0.2f.\
\9\9The bonus scales with your Spellpower and talent level.\
\9\9If you are using a shield this will only occur 50%% of the time.\
\9\9If you are dual wielding this will only occur 50%% of the time.\
\9\9At level 5 the ball becomes radius 2.\
\9\9", "tformat", true) -- 


