section "mod-tome/data/talents/techniques/mobility.lua"

tDef(24, "You must be able to move to use %s!", "logPlayer", true) -- 
tDef(27, "%s is not usable while wearing heavy armour.", "logPlayer", true) -- 
tDef(41, "Disengage", "talent name", true) -- 
tDef(150, "You must disengage directly away from your target in a straight line.", "logPlayer", true) -- 
tDef(169, "You must land in an empty space.", "logPlayer", true) -- 
tDef(177, "Your Disengage was partially blocked.", "logPlayer", true) -- 
tDef(180, "You are not able to Disengage in that direction.", "logPlayer", true) -- 
tDef(198, "Jump back up to %d grids from your target, springing over any creatures in your way. \
\9\9You must disengage in a nearly straight line directly away from your target (which you must be able to see).\
\9\9After moving, you gain %d%% increased movement speed for 3 turns (which ends if you take any actions other than movement), and you may reload your ammo (if any).\
\9\9The extra speed and maximum distance you can move are reduced by your Fatigue level.", "tformat", true) -- 
tDef(207, "Evasion", "talent name", true) -- 
tDef(233, "Your quick wit and reflexes allow you to anticipate attacks against you, granting you a %d%% chance to evade melee and ranged attacks and %d increased defense for %d turns.\
\9\9The chance to evade and defense bonus increase with your Dexterity.", "tformat", true) -- 
tDef(241, "Tumble", "talent name", true) -- 
tDef(268, "You must have an empty space to roll to.", "logPlayer", true) -- 
tDef(281, "In an extreme feat of agility, you move to a spot you can see within range, bounding around, over, or through any enemies in the way.\
\9\9This talent cannot be used while wearing heavy armor, and leaves you exhausted.  The exhaustion increases the cost of your activated Mobility talents by %d%% (stacking), but fades over %d turns.", "tformat", true) -- 
tDef(287, "Trained Reactions", "talent name", true) -- 
tDef(336, "#FIREBRICK##Target# reacts to %s from #Source#, mitigating the blow!#LAST#.", "logCombat", true) -- 
tDef(336, "an attack", "_t", true) -- 
tDef(336, "damage", "_t", true) -- 
tDef(340, " #ffcc80#, -%d stam#LAST#", "tformat", true) -- 
tDef(341, "%s(%d reacted#LAST#%s%s)#LAST#", "tformat", true) -- 
tDef(359, "You have trained to be very light on your feet and have conditioned your reflexes to react faster than thought to damage you take.\
\9\9While this talent is active, you instantly react to any direct damage (not from status effects, etc.) that would hit you for at least %d%% of your maximum life.\
\9\9This requires %0.1f stamina and reduces the damage by %d%%.\
\9\9Your reactions are too slow for this if you are wearing heavy armour.\
\9\9The damage reduction improves with your Defense.", "tformat", true) -- 


