section "mod-tome/data/talents/techniques/throwing-knives.lua"

tDef(101, "Throwing Knives", "talent name", true) -- 
tDef(166, "Throwing Knife", "_t", true) -- 
tDef(186, "%d%% %s", "tformat", true) -- 
tDef(189, "Range: %d\
Net Damage: %d - %d\
Accuracy: %d (%s)\
APR: %d\
Crit Chance: %+d%%\
Crit mult: %d%%\
Uses Stats: %s\
", "tformat", true) -- 
tDef(207, "Equip a bandolier holding up to %d throwing knives, allowing you to attack from range.  You automatically reload %d knives per turn while resting, or half as many while moving.\
\9\9The base power, Armour penetration, and critical strike chance of your knives increase with talent level, accuracy increase with your accuracy, and damage is improved with Dagger Mastery.\
\9\9Throwing Knives count as melee attacks for the purpose of on-hit effects.\
\9\9Effective Throwing Knife Stats:\
\
%s", "tformat", true) -- 
tDef(217, "Fan of Knives", "talent name", true) -- 
tDef(258, "Fan of Knives", "_t", true) -- 
tDef(271, "You keep a special stash of %d throwing knives in your bandolier, which you can throw all at once at enemies within a radius %d cone, for %d%% damage each.\
\9\9Each target can be hit up to 5 times, if the number of knives exceeds the number of enemies.  Creatures block knives from hitting targets behind them.", "tformat", true) -- 
tDef(278, "Precise Aim", "talent name", true) -- 
tDef(292, "You are able to target your throwing knives with pinpoint accuracy, increasing their critical strike chance by %d%% and critical strike damage by %d%%. \
In addition, your critical strikes with throwing knives have a %d%% chance to randomly disable your target, possibly disarming, silencing or pinning them for 2 turns.", "tformat", true) -- 
tDef(299, "Quickdraw", "talent name", true) -- 
tDef(337, "Quickdraw Knife", "_t", true) -- 
tDef(343, "You can throw knives with lightning speed, increasing your attack speed with them by %d%% and giving you a %d%% chance when striking a target in melee to throw a knife at a random foe within 7 tiles for 100%% damage. \
\9\9This bonus attack can only trigger once per turn, and does not trigger from throwing knife attacks.", "tformat", true) -- 
tDef(350, "Venomous Throw", "talent name", true) -- 
tDef(382, "Venomous Throw", "_t", true) -- 
tDef(391, "Throw a knife coated with venom, doing %d%% damage as nature and inflicting additional effects based on your active vile poisons (as per the Venomous Strike talent):\
\9\9\
\9\9%s\
\9\9Using this talent puts your Venomous Strike talent on cooldown.", "tformat", true) -- 


