section "mod-tome/data/talents/techniques/thuggery.lua"

tDef(23, "Skullcracker", "talent name", true) -- 
tDef(63, "%s resists the headblow!", "logSeen", true) -- 
tDef(74, "You smack your forehead against your enemy's head (or whatever sensitive part you can find), causing %0.1f Physical damage.\
\9\9If the attack hits, the target is confused (%d%% effect) for %d turns.\
\9\9Damage done increases with the quality of your headgear, your Strength, and your physical damage bonuses.\
\9\9Confusion power increases with your Dexterity, and chance increases with Accuracy.", "tformat", true) -- 
tDef(83, "Riot-born", "talent name", true) -- 
tDef(95, "Your attunement to violence has given you %d%% resistance to stuns and confusion arising in battle.", "tformat", true) -- 
tDef(100, "Vicious Strikes", "talent name", true) -- 
tDef(112, "You know how to hit the right places, gaining +%d%% critical damage modifier and %d armour penetration.", "tformat", true) -- 
tDef(118, "Total Thuggery", "talent name", true) -- 
tDef(161, "You go all out, trying to burn down your foes as fast as possible.\
\9\9You gain +%d%% attack speed, +%d%% critical chance and +%d%% physical resistance penetration, but this talent drains 6 stamina each turn.\
\9\9This effect is disabled automatically on rest or run.\
\9\9", "tformat", true) -- 


