section "mod-tome/data/talents/techniques/unarmed-discipline.lua"

tDef(22, "Combination Kick", "talent name", true) -- 
tDef(30, "@Source@ unleashes a flurry of disrupting kicks.", "_t", true) -- 
tDef(101, "Unleash a flurry of disruptive kicks at your target's vulnerable areas. For each combo point you attack for %d%% weapon damage and deactivate one physical sustain.\
\9\9\9At talent level 3 #DARK_ORCHID#Magical#LAST# sustains will also be effected.\
\9\9\9At talent level 5 #YELLOW#Mental#LAST# sustains will also be effected.\
\9\9\9Using this talent removes your combo points.", "tformat", true) -- 
tDef(110, "Relentless Strikes", "talent name", true) -- 
tDef(120, "When gaining a combo point, you have a %d%% chance to gain an extra combo point. Additionally, every time you earn a combo point, you will regain %0.2f stamina, or %0.2f stamina if you would exceed 5 combo points.", "tformat", true) -- 
tDef(126, "Open Palm Block", "talent name", true) -- 
tDef(134, "@Source@ prepares to block incoming attacks.", "_t", true) -- 
tDef(149, "Toughen your body blocking up to %d damage per combo point (Max %d) across 2 turns.\
\9\9\9Current block value: %d\
\9\9\9Using this talent removes your combo points.\
\9\9\9The damage absorbed scales with your Physical Power.", "tformat", true) -- 
tDef(159, "Touch of Death", "talent name", true) -- 
tDef(169, "@Source@ strikes a deadly pressure point on the target.", "_t", true) -- 
tDef(191, "#Source# strikes at a vital spot on #target#!", "logCombat", true) -- 
tDef(213, "Using your deep knowledge of anatomy, you strike a target in a vital pressure point for %d%% weapon damage, bypassing their defense and evasion.\
\9\9This strike inflicts terrible wounds inside the target's body, causing them to take physical damage equal to 100%% of any damage dealt during the attack each turn for 4 turns, increasing by %d%% each turn (so after 4 turns, they would have taken a total of %d%% damage).\
\9\9If the target dies while under or from this effect their body will explode in a radius %d shower of bone and gore, inflicting physical damage equal to the current tick to all enemies and granting you 4 combo points.", "tformat", true) -- 


