section "mod-tome/data/talents/techniques/weaponshield.lua"

tDef(24, "Shield Pummel", "talent name", true) -- 
tDef(36, "You require a weapon and a shield to use this talent.", "logPlayer", true) -- 
tDef(41, "You cannot use Shield Pummel without a shield!", "logPlayer", true) -- 
tDef(57, "%s resists the shield bash!", "logSeen", true) -- 
tDef(64, "Hits the target with two shield strikes, doing %d%% and %d%% shield damage. If it hits a second time, it stuns the target for %d turns.\
\9\9The stun chance increases with your Accuracy and your Strength.", "tformat", true) -- 
tDef(73, "Riposte", "talent name", true) -- 
tDef(89, "Improves your ability to perform counterstrikes after blocks in the following ways:\
\9\9Allows counterstrikes after incomplete blocks.\
\9\9Increases the number of counterstrikes you can perform on a target while they're vulnerable by %d.\
\9\9Increases the crit chance of counterstrikes by %d%%. This increase scales with your Dexterity.", "tformat", true) -- 
tDef(97, "Shield Slam", "talent name", true) -- 
tDef(114, "You cannot use Shield Slam without a shield!", "logPlayer", true) -- 
tDef(134, "Hit your target with your shield 3 times for %d%% damage then quickly return to a blocking position.  The bonus block will not check or trigger Block cooldown.", "tformat", true) -- 
tDef(140, "Assault", "talent name", true) -- 
tDef(158, "You cannot use Assault without a mainhand weapon and shield!", "logPlayer", true) -- 
tDef(180, "Hits the target with your shield, doing %d%% damage. If it hits, you follow up with two automatic critical hits with your weapon, doing %d%% base damage each.", "tformat", true) -- 
tDef(190, "Shield Wall", "talent name", true) -- 
tDef(205, "You cannot use Shield Wall without a shield!", "logPlayer", true) -- 
tDef(230, "Enter a protective battle stance allowing you to defend yourself more proficiently while using a shield.\
\9\9Increases Armour by %d, Block value by %d, and reduces Block cooldown by 2.\
\9\9Increases stun and knockback resistance by %d%%.\
\9\9The Armor and Block bonuses increase equally with your Dexterity and Strength.", "tformat", true) -- 
tDef(239, "Repulsion", "talent name", true) -- 
tDef(260, "You cannot use Repulsion without a shield!", "logPlayer", true) -- 
tDef(275, "%s resists the knockback!", "logSeen", true) -- 
tDef(283, "Smash your shield into the face of all adjacent foes dealing %d%% shield damage and knocking them back %d grids.\
\9\9In addition, all creatures knocked back will also be dazed for %d turns.\
\9\9If known, activating this talent will refresh your Rush cooldown if the attack hits.\
\9\9The distance increases with your talent level, and the Daze duration with your Strength.", "tformat", true) -- 
tDef(291, "Shield Expertise", "talent name", true) -- 
tDef(303, "Improves your damage with shield-based skills, and increases your Spell (+%d) and Physical (+%d) Saves.", "tformat", true) -- 
tDef(308, "Last Stand", "talent name", true) -- 
tDef(328, "You cannot use Last Stand without a shield!", "logPlayer", true) -- 
tDef(360, "You brace yourself for the final stand, increasing Defense and Armor by %d, maximum and current life by %d, but making you unable to move.\
\9\9Your stand lets you concentrate on every blow, allowing you to avoid death from normally fatal wounds. You can only die when reaching -%d life.\
\9\9If your life is below 0 when Last Stand ends it will be set to 1.\
\9\9The increase in Defense and Armor is based on your Dexterity, and the increase in life is based on your Constitution and normal maximum life.", "tformat", true) -- 


