section "mod-tome/data/talents/uber/const.lua"

tDef(20, "Draconic Body", "talent name", true) -- 
tDef(23, "Be close to the draconic world", "_t", true) -- 
tDef(28, "%s's draconic body hardens and heals!", "logSeen", true) -- 
tDef(32, "Your body hardens and recovers quickly. When pushed below 30%% life, you instantly restore 40%% of your total life.", "tformat", true) -- 
tDef(38, "Bloodspring", "talent name", true) -- 
tDef(41, "Have let Melinda be sacrificed", "_t", true) -- 
tDef(60, "When a single blow deals more than 15%% of your total life, a torrent of blood gushes from your body, creating a bloody tidal wave for 4 turns that deals %0.2f blight damage, heals you for 50%% of the damage done, and knocks foes back.\
\9\9The damage increases with your Constitution.", "tformat", true) -- 
tDef(67, "Eternal Guard", "talent name", true) -- 
tDef(69, "Know the Block talent", "_t", true) -- 
tDef(71, "Your Block talent now lasts for 2 game turns and you can apply Counterstrike to any number of enemies.", "tformat", true) -- 
tDef(77, "Never Stop Running", "talent name", true) -- 
tDef(83, "Know at least 20 levels of stamina-using talents", "_t", true) -- 
tDef(93, "While this talent is active, you dig deep into your stamina reserves, allowing you to move without taking a turn. However, this costs 12 stamina for each tile that you cross.", "tformat", true) -- 
tDef(98, "Armour of Shadows", "talent name", true) -- 
tDef(100, "Have dealt over 50000 darkness damage", "_t", true) -- 
tDef(113, "You know how to protect yourself with the deepest shadows. As long as you stand on an unlit tile you gain %d armour, 50%% armour hardiness, and 20%% evasion.\
\9\9Any time you deal darkness damage, you will unlight both the target tile and yours.\
\9\9Passively increases your stealth rating by %d.\
\9\9The armor bonus scales with your Constitution.", "tformat", true) -- 
tDef(122, "Spine of the World", "talent name", true) -- 
tDef(129, "Your back is as hard as stone. Each time that you are affected by a physical effect, your body hardens, making you immune to all other physical effects for 5 turns.", "tformat", true) -- 
tDef(135, "Fungal Blood", "talent name", true) -- 
tDef(136, "Be able to use infusions", "_t", true) -- 
tDef(166, "Fungal spores have colonized your blood, so that each time you use an infusion you store %d fungal power.\
\9\9You may use this prodigy to release the power as a heal (never more than %d life) and remove up to 10 detrimental magical effects.\
\9\9Fungal power lasts for up to 6 turns, losing the greater of 10 potency or 10%% of its power each turn.\
\9\9The amount of fungal power produced and the maximum heal possible increase with your Constitution and maximum life.", "tformat", true) -- 
tDef(175, "Corrupted Shell", "talent name", true) -- 
tDef(177, "Have received at least 3500 blight damage and destroyed Zigur with the Grand Corruptor.", "_t", true) -- 
tDef(194, "Thanks to your newfound knowledge of corruption, you've learned some tricks for toughening your body... but only if you are healthy enough to withstand the strain from the changes.\
\9\9Improves your life by 500, your defense by %d, your armour by %d, your armour hardiness by 20%% and your saves by %d as your natural toughness and reflexes are pushed beyond their normal limits.\
\9\9Your saves armour and defense will improve with your Constitution.", "tformat", true) -- 


