tDef(152, "You unleash a blast of #LIGHT_STEEL_BLUE#temporal#LAST# energy!", "logSeen", true) -- 
tDef(156, "You unleash a blast of #DARK_GREEN#virulent blight!#LAST#!", "logSeen", true) -- 
tDef(162, "You unleash a blast of #GREEN#acid#LAST#!", "logSeen", true) -- 
tDef(166, "You unleash a blast of numbing #GREY#darkness#LAST#!", "logSeen", true) -- 
