section "mod-tome/data/talents/uber/dex.lua"

tDef(20, "Flexible Combat", "talent name", true) -- 
tDef(31, "Each time that you make a melee attack you have a 50%% chance to execute an additional unarmed strike.", "tformat", true) -- 
tDef(37, "Through The Crowd", "talent name", true) -- 
tDef(38, "Have had at least 6 party members at the same time", "_t", true) -- 
tDef(81, "You are used to a crowded party:\
\9\9- you can swap places with friendly creatures in just one tenth of a turn as a passive effect.\
\9\9- you can never damage your friends or neutral creatures while this talent is active.\
\9\9- you love being surrounded by friends; for each friendly creature in sight you gain +10 to all saves and +3%% to global speed (max 15%%)\
\9\9- every party member is also automatically granted Through The Crowd", "tformat", true) -- 
tDef(92, "Manage Swift Hands", "talent name", true) -- 
tDef(97, "You can only prepare your swift hands tools outside of combat.", "logPlayer", true) -- 
